L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "어느 정도 예상은 했지만, 역시 미성년자셨군요."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ある程度予想はしていましたが、やはり未成年者でしたか。"
L4_1.m_Talk_ENG = "I kind of expected it, but you're a minor..."
L4_1.m_Talk_TWN = "雖然有猜到，結果還真的未成年。"
L4_1.m_Talk_THA = "ก็กะไว้แล้วแหละครับ แต่คุณยังเป็นผู้เยาว์อยู่เลย..."
L4_1.m_Talk_VTN = "Tôi cũng mong đợi vậy, nhưng cô là trẻ vị thành niên mà..."
