L4_1.m_Talk_DEU = "Ich habe es irgendwie erwartet, aber Sie sind ja auch minderjährig ..."
L4_1.m_Talk_FRA = "Vous êtes mineure, n'est-ce pas ? Je m'y attendais un peu."
