L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ふざけるな！　こう見えても将校だ！　大人なんだ！"
L5_1.m_Talk_ENG = "Nuh-uh! I'm an adult! An officer!"
L5_1.m_Talk_TWN = "笑死啦！我可是軍官欸！我是大人！"
