L5_1.m_Talk_VTN = "NUH uh! Tôi là một người lớn! Một sĩ quan!"
L5_1.m_Talk_SCN = "别逗了！别看我这样，我可是军官！是大人了！"
L5_1.m_Talk_DEU = "Mach dich nicht lächerlich! Ich bin erwachsen! Ich bin eine Offizierin!"
L5_1.m_Talk_FRA = "Te fous pas de moi, je suis un officier ! Une adulte, donc !"
