L16_1.m_Face = "UNIT_IDLE"
L16_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L16_1.m_Pos = "R"
L16_1.m_Talk_KOREA = "내 아버지는 왕실 최고 기술자로서 폐하의 신임을 한몸에 받던 분이셨다."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "私の父は王室の最高技術者として陛下の信頼を一身に受けていた方だった。"
L16_1.m_Talk_ENG = "My father was once the Royal Chief Technician, and His Majesty had great faith in him."
L16_1.m_Talk_TWN = "我父親是皇室頂尖技師，深受陛下信任。"
L16_1.m_Talk_THA = "พ่อฉันเคยเป็นหัวหน้าช่างเทคนิคหลวงนะ และฝ่าบาทก็เชื่อถือเขามาก"
L16_1.m_Talk_VTN = "Bố tôi đã từng là Kỹ sư trưởng Hoàng gia, và Nhà Vua rất tin tưởng ông ấy."
L16_1.m_Talk_SCN = "我父亲是皇家首席技术员，深得陛下信任。"
L16_1.m_Talk_DEU = "Mein Vater war einst der königliche Cheftechniker und Seine Majestät hatte großes Vertrauen in ihn."
L16_1.m_Talk_FRA = "Mon père était Technicien en chef avant moi, et Sa Majesté lui vouait une confiance absolue."
