L18_1.m_Face = "UNIT_IDLE"
L18_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "평민 출신임에도 방계 왕족이셨던 어머니와 혼사를 치를 정도였어."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "平民出身にも関わらず、傍系の王族だった母と結婚するくらいだったからな。"
L18_1.m_Talk_ENG = "Enough so that even being born a commoner, he got to marry royalty."
L18_1.m_Talk_TWN = "雖然出身平民，卻還是和旁系皇族的母親結婚。"
L18_1.m_Talk_THA = "มากจนถึงจะมีชาติกำเนิดเป็นสามัญชน แต่ก็ได้แต่งงานกับราชวงศ์"
L18_1.m_Talk_VTN = "Đến mức, ngay cả khi sinh ra là một thường dân, ông ấy vẫn được kết hôn với hoàng tộc."
L18_1.m_Talk_SCN = "虽然是平民出身，但还是跟出身王室旁系的母亲结了婚。"
L18_1.m_Talk_DEU = "So viel soagr, dass er, obwohl er als Bürgerlicher geboren wurde, eine Adelige heiraten konnte."
L18_1.m_Talk_FRA = "Suffisamment pour lui autoriser d'épouser une noble, lui qui était pourtant roturier."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "BORDER_ACT2_INTERLUDE6@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 4500212
L19_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "하지만 아버지의 상관이 뒤집어쓴 오명 때문에, 우리 가문의 명예마저 바닥으로 실추하고 말았지."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "だが、父の上官が汚名を着せられたせいで、私の家門の名誉もまた失墜してしまったんだ。"
L19_1.m_Talk_ENG = "But due to my father's superior being branded as a traitor, our family's honor was ruined."
L19_1.m_Talk_TWN = "只是因爲父親的上司的抹黑而蒙受污名，導致連我們家族的名譽掃地。"
L19_1.m_Talk_THA = "แต่พอผู้บังคับบัญชาของพ่อโดนตราหน้าว่าเป็นกบฏ เกียรติของครอบครัวเราก็ต้องพังทลายลง"
L19_1.m_Talk_VTN = "Nhưng do cấp trên của bố tôi bị coi là kẻ phản bội, danh dự của gia đình chúng tôi đã bị hủy hoại."
L19_1.m_Talk_SCN = "不过因为父亲的上司被认定为叛徒，我们家族的荣誉也坠到了谷底。"
L19_1.m_Talk_DEU = "Aber weil der Vorgesetzte meines Vaters als Verräter gebrandmarkt wurde, wurde die Ehre unserer Familie beschmutzt."
L19_1.m_Talk_FRA = "Mais lorsque son supérieur a été accusé de traîtrise, l'honneur de notre famille a volé en éclat."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "BORDER_ACT2_INTERLUDE6@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 4500212
L20_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "가문의 명예를 다시 드높이고자 나 또한 최고가 되려 노력했지만…"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "家門の名誉を再び高めようと、私もまた最高となるべく努力したが……"
L20_1.m_Talk_ENG = "I've tried my best to restore my family's honor, but..."
L20_1.m_Talk_TWN = "我很努力要成為頂尖，使家族能夠恢復的名聲……"
L20_1.m_Talk_THA = "ฉันพยายามที่สุดแล้วที่จะกูเกียรติของครอบครัวคืนมา แต่ก็..."
L20_1.m_Talk_VTN = "Tôi đã cố gắng hết sức để khôi phục lại danh dự cho gia đình mình, nhưng..."
L20_1.m_Talk_SCN = "为了重振家族荣誉，我也努力成为最优秀的人……"
L20_1.m_Talk_DEU = "Ich habe mein Bestes gegeben, um die Ehre meiner Familie wiederherzustellen, aber ..."
L20_1.m_Talk_FRA = "J'ai fait de mon mieux pour le restaurer comme je pouvais, mais..."
