L22_1 = {}
L22_1.m_CutScenKey_Talk = "BORDER_ACT2_INTERLUDE6@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 4500212
L22_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L22_1.m_Talk_KOREA = "내가 아무리 노력해도, 오명의 멍에를 떨쳐내기엔 역부족이더군."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "いくら頑張っても、汚名という首枷から逃れるには力不足だった。"
L22_1.m_Talk_ENG = "No matter how hard I tried, it wasn't enough to wash off the shame."
L22_1.m_Talk_TWN = "但不管我怎麼努力，就是無法擺脫污名的枷鎖。"
L22_1.m_Talk_THA = "ไม่ว่าจะพยายามขนาดไหน ก็ยังไม่พอจะลบล้างความน่าละอายนั้นไปได้"
L22_1.m_Talk_VTN = "Dù tôi có cố gắng thế nào cũng không đủ để gột rửa sự ô nhục này."
L22_1.m_Talk_SCN = "可是不管我怎么努力，还是不足以摆脱污名的枷锁。"
L22_1.m_Talk_DEU = "So sehr ich es auch versuchte, es reichte nicht aus, um den Namen meiner Familie wieder reinzuwaschen."
L22_1.m_Talk_FRA = "Mes efforts n'ont pas suffit à faire disparaître la honte que j'éprouvais."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "BORDER_ACT2_INTERLUDE6@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 4500212
L23_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "그래서 이곳에 오신 거군요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "それでここにいらしたわけですか。"
L23_1.m_Talk_ENG = "So that's the real reason you're here."
L23_1.m_Talk_TWN = "所以才來這裡嗎。"
L23_1.m_Talk_THA = "นั่นสินะเหตุผลจริงๆ ที่คุณมาที่นี่"
L23_1.m_Talk_VTN = "Vậy ra, đó là lý do thực sự khiến cô ở đây."
L23_1.m_Talk_SCN = "所以您才会来到这里啊。"
L23_1.m_Talk_DEU = "Das ist also der wahre Grund, warum Sie hier sind."
L23_1.m_Talk_FRA = "Je vois. C'est donc pour ça que vous êtes ici."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "BORDER_ACT2_INTERLUDE6@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 4500212
L24_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "성유물과 함께 잃어버린 명예를 되찾기 위해서."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "聖遺物と共に、失われた名誉を取り戻すために。"
L24_1.m_Talk_ENG = "To find the Holy Relic and restore your family's honor."
L24_1.m_Talk_TWN = "跟聖遺物一起找回失去的名聲。"
L24_1.m_Talk_THA = "เพื่อหาสิ่งตกทอดศักดิ์สิทธิ์และกู้เกียรติยศให้ครบครัว"
L24_1.m_Talk_VTN = "Để tìm Thánh Tích và khôi phục danh dự cho gia đình mình."
L25_1 = "为了重新找回圣遗物和失去的荣誉。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Um das Heilige Artefakt zu finden und die Ehre Ihrer Familie wiederherzustellen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Pour trouver la Sainte Relique et restaurer l'honneur de votre famille."
L24_1.m_Talk_FRA = L25_1
