L27_1 = "BORDER_ACT2_INTERLUDE6@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4500212
L26_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SERIOUS"
L26_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "이건, 지금까지 귀관이 내게 거짓말을 하지 않았기에 특별히 하는 얘기다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "これは、今まで貴官が私に嘘をつかなかったから特別に話したんだ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I'm telling you this in confidence because you didn't lie to me."
L26_1.m_Talk_ENG = L27_1
L27_1 = "因爲你從來沒有對我說過謊，我才特別告訴你的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันมั่นใจจะบอกคุณเรื่องนี้เพราะคุณไม่โกหกฉัน"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi nói với anh điều này một cách tự tin bởi vì anh đã không nói dối tôi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "这是因为到现在为止你都没有跟我说谎，我才特别跟你讲的。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich erzähle dir das im Vertrauen, weil du mich nicht angelogen hast."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Si j'accepte de te dire tout ça, c'est parce que tu ne m'as pas menti."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "BORDER_ACT2_INTERLUDE6@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4500212
L27_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_PRIDE"
L27_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "나 같은 귀족은 공정함을 중요시하는 법이니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "私のような貴族は公平を重視してるからな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Nobility like me always value fairness above all else."
L27_1.m_Talk_ENG = L28_1
L28_1 = "畢竟像我這樣的貴族很講求公正的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ชนชั้นสูงอย่างฉันให้ค่าเรื่องความยุติธรรมเหนือสิ่งอื่นใดเสมอ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Giới quý tộc như tôi luôn coi trọng sự công bằng hơn tất cả."
L27_1.m_Talk_VTN = L28_1
L28_1 = "像我这样的贵族可是很重视公平的！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Adlige wie ich legen den größten Wert auf Fairness."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Les nobles de ma trempe se démarquent avant tout par leur sens de la justice."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "BORDER_ACT2_INTERLUDE6@28#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 28
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4500212
L28_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "UNIT_LAUGH"
L28_1.m_Face = L29_1
L28_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L28_1.m_Pos = "C"
L29_1 = "저를 믿어주셨다니 기쁘군요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私を信頼してくださっているなんて、嬉しいですね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I'm glad to hear that you trust me."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我很高興你相信我。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ได้ยินว่าคุณไว้ใจผมก็ดีใจครับ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi rất vui khi biết rằng cô tin tưởng tôi."
L28_1.m_Talk_VTN = L29_1
L29_1 = "我很开心您能信任我。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich bin froh zu hören, dass Sie mir vertrauen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je suis content de constater que j'ai votre confiance."
L28_1.m_Talk_FRA = L29_1
