L31_1 = {}
L32_1 = "BORDER_ACT2_INTERLUDE6@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4500212
L31_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_HATE"
L31_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L31_1.m_Pos = "R"
L32_1 = "아니, 난 지금도 귀관을 완전히 신뢰하지 않아."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "いや、私は今も貴官を完全に信頼してはいない。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "No, I still don't completely trust you."
L31_1.m_Talk_ENG = L32_1
L32_1 = "不，我現在也不是完全信任你。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่สิ ฉันยังไม่ไว้คุณทั้งหมดหรอก"
L31_1.m_Talk_THA = L32_1
L32_1 = "Không, tôi vẫn chưa hoàn toàn tin tưởng anh đâu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不，我现在也没有完全信任你。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nein, ich vertraue dir immer noch nicht ganz."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Non, je n'irai pas jusque là."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "BORDER_ACT2_INTERLUDE6@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4500212
L32_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L32_1.m_Pos = "R"
L33_1 = "다만 오명을 뒤집어쓰고 좌절을 겪는 이가 있다면, 그것을 좌시하지 않을 뿐."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ただ汚名を着せられて絶望している者がいるなら、それを放っておけないだけだ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "However, if someone has experienced something similar to what I have, I don't just stand there and watch."
L32_1.m_Talk_ENG = L33_1
L33_1 = "但若是有人也蒙受不白之冤，那我是不會坐視不管的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่จะยังไง ถ้ามีใครที่เจออะไรแบบฉัน ฉันจะไม่นิ่งดูดาย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tuy nhiên, nếu ai đó đã trải qua điều gì đó tương tự như những gì tôi đã trải qua, tôi sẽ không chỉ đứng đó và nhìn đâu."
L32_1.m_Talk_VTN = L33_1
L33_1 = "我只是不会对背负着污名、遭受挫折的人坐视不理而已。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wenn jedoch jemand etwas Ähnliches wie ich erlebt hat, stehe ich nicht einfach da und schaue zu."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Mais tu sembles avoir vécu une tragédie similaire à la mienne, alors je n'allais pas rester là sans rien dire."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
