L34_1 = "그게 하물며 내 가문을 궁지로 몰았던 내 아버지 데이빗 래시포드의 상관…!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それが家門を窮地に追い込んだ、父デイビッド・ラッシュフォードの上官……！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Even if that person was David Rashford's superior...!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "更何況是把我們家逼到絕境的父親 大衛·雷斯福特的上司…！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ต่อให้คนคนนั้นเป็นผู้บังคับบัญชาของเดวิด แรชฟอร์ดก็ถอะ...!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Kể cả khi người đó là cấp trên của David Rashford...!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "就算他是把我的家族逼入绝境，我父亲戴维·拉什福德曾经的上司……！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Auch wenn diese Person David Rashfords Vorgesetzter wäre ...!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Et tout ça, même en sachant que c'était toi, le supérieur de l'adjudant David Rashford !"
L33_1.m_Talk_FRA = L34_1
