L46_1 = "UNIT_SURPRISE"
L45_1.m_Face = L46_1
L46_1 = "ELLA_BORDER_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "R"
L46_1 = "돌 떨어지는 소리가 나서 들어와 봤는데. 무슨 일이야?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "岩が落ちるような音がしたから入ってきたんだけど。どうしたの？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I heard a thud. Is everything all right here?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我好像有聽到石頭掉落的聲音，所以進來一看一下，怎麼回事？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ได้ยินเสียงอะไรดังตุ้บ ทุกอย่างเรียบร้อยดีใช่มั้ยนะ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi nghe thấy một tiếng uỵch. Mọi thứ ở đây đều ổn chứ?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "发生什么事了？打雷了吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich hörte ein dumpfes Geräusch. Ist hier alles in Ordnung?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tout va bien, ici ? J'ai entendu du bruit."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "BORDER_ACT2_INTERLUDE6@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4500212
L46_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_LAUGH"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L47_1 = "L"
L46_1.m_Pos = L47_1
L47_1 = "…별 일 아니다. 장교님께서 아무래도 술에 강한 편은 아니신 것 같군."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "……大したことではない。将校はどうやら酒に強い方ではなさそうだな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Yes. It appears that our officer is a lightweight."
L46_1.m_Talk_ENG = L47_1
L47_1 = "…沒什麼，看來軍官不太會喝酒。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ใช่ กลายเป็นว่าเจ้าหน้าที่ของเราเป็นพวกคออ่อนน่ะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đúng. Có vẻ như sĩ quan của chúng ta không biết uống bia."
L46_1.m_Talk_VTN = L47_1
L47_1 = "……没什么事。军官好像不怎么会喝酒。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ja. Es scheint, dass unsere Offizierin nicht so trinkfest ist."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oui. Il semblerait que notre chère Technicienne en chef ne tient pas vraiment l'alcool."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "BORDER_ACT2_INTERLUDE6@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 4500212
L47_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L48_1 = "ELLA_BORDER_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "R"
L48_1 = "맡겨 둬. 내가 방까지 모셔드릴게."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "任せて。私が部屋まで連れていくから。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Let me handle it. I'll take her back to her room."
L47_1.m_Talk_ENG = L48_1
L48_1 = "交給我吧，我送她回房間。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันจัดการเอง เดี๋ยวฉันพาเธอกลับห้อง"
L47_1.m_Talk_THA = L48_1
L48_1 = "Hãy để tôi xử lý cho. Tôi sẽ đưa cô ấy về phòng."
L47_1.m_Talk_VTN = L48_1
L48_1 = "交给我吧。我送她回房间。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Überlass das ruhig mir! Ich bringe sie zurück in ihr Zimmer."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je vois. Je m'occupe de la ramener jusqu'à sa chambre."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
