L3_1 = "으으음… 골이 깨진 것처럼 아프군."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "うーむ……頭が割れるように痛いな。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Ugh... My head's pounding..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "呃呃嗯… 頭好痛喔。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "โอย... หัวยังกะจะระเบิด..."
L2_1.m_Talk_THA = L3_1
L3_1 = "Ugh... Đầu tôi đau như sắp nổ tung vậy..."
L2_1.m_Talk_VTN = L3_1
L3_1 = "呃呃嗯……脑袋疼得像是要爆炸了一样。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Urgh ... Mein Kopf tut so weh, als ob er gleich platzen würde ..."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Argh... ma tête..."
L2_1.m_Talk_FRA = L3_1
