L4_1 = "이게 숙취라는 건가?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "これが二日酔いというものなのか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Is this what a hangover feels like?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "這就是宿醉嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เมาแฮงก์มันเป็นแบบนี้เองเหรอเนี่ย?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đây có phải là cảm giác nôn nao không?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "这就是宿醉吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Fühlt sich so ein Kater an?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "C'est ça, ce qu'on appelle la gueule de bois ?"
L3_1.m_Talk_FRA = L4_1
