L5_1 = "BORDER_ACT2_INTERLUDE6@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4500212
L4_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
