L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "가벼운 외상입니다. 목공탁자에 머리를 찧으셨어요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "軽い外傷です。木工テーブルに頭をおぶつけになりました。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "It's light trauma. You hit your head on the table."
L4_1.m_Talk_ENG = L5_1
L5_1 = "是輕微的外傷，你的頭撞到木頭桌子。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เป็นแผลเล็กๆ หรอก คุณหัวฟาดโต๊ะน่ะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Chỉ là chấn thương nhẹ thôi. Cô đập đầu vào bàn đấy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "是轻微的外伤。您的头撞到木桌上了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Es ist nur ein leichtes Trauma. Sie sind mit Ihrem Kopf auf den Tisch geschlagen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Non, vous avez une légère commotion après vous être frappé la tête contre une table."
L4_1.m_Talk_FRA = L5_1
