L6_1 = "UNIT_SURPRISE"
L5_1.m_Face = L6_1
L5_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "으음… 수비대장…?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ううん……守備隊長？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Hmm...? Guard Captain?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "呃嗯…護衛隊長…？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หืมม...? หัวหน้าองครักษ์เหรอ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Hmm...? Đội trưởng Đội cận vệ?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "呃嗯……护卫队队长……？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hmm ...? Grenzschutzkommandantin?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Hmm...? Capitaine ?"
L5_1.m_Talk_FRA = L6_1
