L6_1.m_Face = "UNIT_HATE"
L6_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L7_1 = "L_F_C"
L6_1.m_Pos = L7_1
L7_1 = "부축하지 않아도 돼. 혼자 걸을 수 있다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "手を貸さずともよい。一人で歩ける。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You can put me down. I can walk by myself."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不用扶我，我自己能走。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "วางฉันลงได้แล้ว ฉันเดินเองได้"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô có thể đặt tôi xuống. Tôi tự đi bộ được."
L6_1.m_Talk_VTN = L7_1
L7_1 = "不用扶我，我自己能走。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Du kannst mich loslassen. Ich kann alleine gehen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu peux me laisser, je peux marcher seule."
L6_1.m_Talk_FRA = L7_1
