L8_1 = "BORDER_ACT2_INTERLUDE6@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500212
L7_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "ELLA_BORDER_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R"
L8_1 = "이마에 혹이 났는데, 약이라도 발라드려요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "額にこぶができていますが、薬でも塗りましょうか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You got a big bump on your head. Do you want some ointment for that?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你額頭上腫一個大包，要不要給你抹點藥？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "หัวคุณโนเบ้อเริ่มเลยนะ ให้เอาขี้ผึ้งมาทามั้ย?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đầu cô bị sưng lớn đấy. Cô có muốn lấy một ít thuốc mỡ không?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "额头撞起包了，用给您抹点药吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie haben eine große Beule am Kopf. Wollen Sie eine Salbe dafür?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Acceptez au moins cette pommade. Votre bosse est assez grosse..."
L7_1.m_Talk_FRA = L8_1
