L9_1 = "BORDER_ACT2_INTERLUDE6@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4500212
L8_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "괜찮다. 통증 덕에 술도 깼어."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "大丈夫だ。痛みのおかげで酔いが覚めた。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "It's okay. The pain's sobering me up a bit."
L8_1.m_Talk_ENG = L9_1
L9_1 = "沒關係，疼痛可以讓我醒酒。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ไม่เป็นไร เจ็บแล้วค่อยสร่างหน่อย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Không sao đâu. Cơn đau làm tôi tỉnh táo hơn một chút."
L8_1.m_Talk_VTN = L9_1
L9_1 = "没事……现在疼得酒也醒了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Schon okay. Der Schmerz lässt mich ein bisschen ausnüchtern."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ça va, la douleur m'aide à dégriser."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "BORDER_ACT2_INTERLUDE6@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500212
L9_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "그리고… 자네에겐 이 말을 전하고 싶군."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それに……あなたに伝えたい言葉がある。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Also... I have something to tell you."
L9_1.m_Talk_ENG = L10_1
L10_1 = "還有… 我有句話想告訴你。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แล้วก็... ฉันมีอะไรจะบอกคุณด้วย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ngoài ra... Tôi có vài điều muốn nói với cô."
L9_1.m_Talk_VTN = L10_1
L10_1 = "还有……有些话我一直想对你说。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Außerdem ... habe ich dir etwas zu sagen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, et il faut que je te dise quelque chose."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "BORDER_ACT2_INTERLUDE6@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4500212
L10_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L11_1 = "L"
L10_1.m_Pos = L11_1
L11_1 = "이번 임무를 도와준 것에 뒤늦게나마 감사를 표한다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "今度の任務を手伝ってくれたことに、遅ればせながら感謝する。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I want to express my gratitude for helping me out on my mission."
L10_1.m_Talk_ENG = L11_1
L11_1 = "謝謝你們幫忙這次任務的幫助，這是遲來的感謝。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฉันอยากแสดงความขอบคุณที่ช่วยฉันทำภารกิจน่ะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi muốn bày tỏ lòng biết ơn vì cô đã giúp tôi thực hiện nhiệm vụ của mình."
L10_1.m_Talk_VTN = L11_1
L11_1 = "虽然有些迟了，但我还是想对这次任务中你给予的帮助表示感谢。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Auch wenn es schon ein bisschen zu spät dafür ist, aber ich möchte mich dafür bedanken, dass du mir bei meiner Mission geholfen hast."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je voulais... t'exprimer ma gratitude pour m'avoir aidé dans ma mission."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "BORDER_ACT2_INTERLUDE6@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4500212
L11_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "ELLA_BORDER_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "R"
L12_1 = "…왕립군의 일원으로서 당연히 해야 할 일을 했을 뿐입니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……王立軍の一員としての責務を果たしたまでです。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I was just doing what any other member of the Royal Army would do."
L11_1.m_Talk_ENG = L12_1
L12_1 = "……我身為皇家軍隊的一員，只是做我份內該做的事。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันแค่ทำเรื่องที่สมาชิกคนไหนของทัพหลวงก็คงทำกันเองค่ะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi chỉ đang làm điều mà bất kỳ thành viên nào khác của Quân đội Hoàng gia sẽ làm."
L11_1.m_Talk_VTN = L12_1
L12_1 = "……身为皇家军队的一员，这些都是我应该做的。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich habe einfach das getan, was jedes andere Mitglied der königlichen Armee getan hätte."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je ne faisais que mon devoir. Tous les soldats de l'armée royale en auraient fait de même à ma place."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "BORDER_ACT2_INTERLUDE6@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500212
L12_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_DESPAIR"
L12_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L13_1 = "L"
L12_1.m_Pos = L13_1
L13_1 = "귀관이 만든 감자 스튜… 제법 맛있더군."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "貴官の作ったジャガイモのシチュー……なかなかおいしかった。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "That stew you made... It was pretty good."
L12_1.m_Talk_ENG = L13_1
L13_1 = "你做的馬鈴薯濃湯… 還蠻好吃的。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "สตูว์ที่คุณทำน่ะ... อร่อยเลยนะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Món hầm cô làm... Nó khá ngon."
L12_1.m_Talk_VTN = L13_1
L13_1 = "你做的土豆炖菜……相当好吃。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dieser Kartoffeleintopf, den du gemacht hast ... war ziemlich gut."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Et ce ragoût que tu as préparé ce soir... il était délicieux."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "BORDER_ACT2_INTERLUDE6@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500212
L13_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "ELLA_BORDER_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L14_1 = "…마음에 드셨다면, 내일 아침까진 드시고 가시죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "……お気に召したなら、明日の朝食も召し上がっていってください。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "If you liked it so much you can have some more tomorrow before you leave."
L13_1.m_Talk_ENG = L14_1
L14_1 = "…喜歡的話，明天早上吃完再走吧。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ถ้าชอบขนาดนั้น พรุ่งนี้กินอีกก่อนไปได้นะคะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nếu cô thích nó đến vậy, cô có thể ăn thêm vào ngày mai trước khi rời đi."
L13_1.m_Talk_VTN = L14_1
L14_1 = "……您喜欢的话，明天早晨吃完早饭再走吧。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Wenn er Ihnen so gut gefallen hat, können Sie morgen vor Ihrer Abreise noch etwas davon haben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "S'il vous a plus, je vous en resservirai demain avant votre départ."
