L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4500212
L23_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "WILBUR_NPC_FAKE_MASKED"
L23_1.m_CharStrID = L24_1
L24_1 = "저희 회사와의 협업을 흔쾌히 받아들여 주신 노르드나빅의 재건단 분들에게 불미스러운 사고 소식으로 먼저 연락을 드리게 되어 유감입니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "私共の会社との協業を快く受けれ入れてくださったノルドナビック再建団のみなさんに、不始末な事故のことで連絡することとなり残念に思っております。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I'm terribly sorry to have to inform the Nordnavik National Reconstruction Alliance, who were excited to work with us, about the unfortunate accident."
L23_1.m_Talk_ENG = L24_1
L24_1 = "很遺憾，一個不幸的消息，要告訴爽快與我們公司合作的諾爾德萊比重建委員會成員。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ผมมีความเสียใจจริงๆ ที่จะต้องแจ้งให้พันธมิตรฟื้นฟูชาตินอร์ดเนวิก ซึ่งตื่นเต้นที่จะได้ร่วมงานกับเรา ทราบถึงอุบัติเหตุที่น่าเศร้า"
L23_1.m_Talk_THA = L24_1
L24_1 = "Liên minh Tái thiết Quốc gia Nordnavik đã vui lòng hợp tác với chúng tôi, nhưng tôi rất tiếc phải thông báo về vụ tai nạn không may."
L23_1.m_Talk_VTN = L24_1
L24_1 = "诺德纳维克重建同盟的诸位欣然接受了我们公司的合作提议，但我给您打这通电话，却不得不告诉您一个不好的消息。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Es tut mir schrecklich leid, Nordnaviks Wiederaufbaustiftung, die sich auf die Zusammenarbeit mit uns gefreut hat, über den unglücklichen Vorfall informieren zu müssen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Veuillez excuser cet appel tardif, mais j'ai le regret de devoir annoncer à l'Alliance de reconstruction de Nordnavik une terrible nouvelle."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
