L28_1 = "WILBUR_NPC_FAKE_MASKED"
L27_1.m_CharStrID = L28_1
L28_1 = "다름이 아니라 저희가 3개월 전 성유물 조사를 위해 파견을 약속드렸던 직원 한나 엔더슨 양에 대한 얘깁니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "実は、こちらで3カ月前に聖遺物の調査のために派遣するとお約束した職員、ハンナ・アンダーソンのことなんですが。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It's about none other than Hanna Anderson, the employee we promised to send out for the Holy Relic investigation 3 months ago."
L27_1.m_Talk_ENG = L28_1
L28_1 = "是這樣的，是關於我們三個月前派去調查聖遺物的職員 漢娜·安德森小姐。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เรื่องฮันนา แอนเดอร์สันน่ะครับ พนักงานที่เมื่อ 3 เดือนก่อนเราสัญญาว่าจะส่งไปตามหาสิ่งตกทอดศักดิ์สิทธิ์"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đó không ai khác chính là Hanna Anderson, nhân viên mà chúng tôi đã hứa sẽ cử đi điều tra Thánh Tích 3 tháng trước."
L27_1.m_Talk_VTN = L28_1
L28_1 = "是这样的，跟我们3个月前答应派去调查圣遗物的职员汉娜·安德森有关。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Es geht um niemand geringeren als Hanna Anderson, die Mitarbeiterin, die wir vor drei Monaten für die Untersuchung des Heiligen Artefakts zu schicken versprochen hatten."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il s'agit de Hanna Anderson, l'employée que nous avions promis de vous envoyer il y a 3 mois pour mener l'enquête à propos de la Sainte Relique..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
