L29_1 = "WILBUR_NPC_FAKE_MASKED"
L28_1.m_CharStrID = L29_1
L29_1 = "엔더슨 양으로 확인되는 시신이 오늘 아침 해안가에서 발견되어 지금 막 수습된 참입니다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "アンダーソンと確認された死体が今朝海岸で見つかり、今やっと収拾がついたところでして。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Miss Anderson's body was discovered on the beach this morning and has just been recovered."
L28_1.m_Talk_ENG = L29_1
L29_1 = "今早在海邊發現安德森小姐的屍體，現在才剛處理好。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เราเพิ่งพบศพคุณแอนเดอร์สันที่ชายหาดเมื่อเช้านี้ และเพิ่งนำศพกลับมาได้ครับ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Thi thể của cô Anderson được phát hiện trên bãi biển sáng nay và vừa được tìm thấy."
L28_1.m_Talk_VTN = L29_1
L29_1 = "今天早晨我们在海边发现了确认是安德森的尸体，现在才刚处理完。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Frau Andersons Leiche wurde heute Morgen am Strand entdeckt und gerade geborgen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Le corps de Mme Anderson a été découvert échoué sur une plage ce matin. Nous venons de le récupérer."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "BORDER_ACT2_INTERLUDE6@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4500212
L29_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "WILBUR_NPC_FAKE_MASKED"
L29_1.m_CharStrID = L30_1
L30_1 = "파견 당일 크루즈를 타고 이동하던 중 누군가에게 살해당한 것 같더군요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "派遣の当日、クルーズに乗って移動している途中に誰かによって殺されたようなんです。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "We believe she was murdered on the cruise ship the day she was deployed."
L29_1.m_Talk_ENG = L30_1
L30_1 = "出發當天搭乘郵輪移動時，似乎在途中遭人殺害。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เราเชื่อว่าเธอถูกฆาตกรรมบนเรือสำราญที่ไปปฏิบัติงาน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chúng tôi tin rằng cô ấy đã bị sát hại trên du thuyền vào ngày cô ấy được triển khai."
L29_1.m_Talk_VTN = L30_1
L30_1 = "她好像是在派遣当天乘坐邮轮前往目的地的途中被人杀害了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wir glauben, dass sie am Tag ihres Einsatzes auf dem Kreuzfahrtschiff ermordet wurde."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Nous avons des raisons de penser qu'elle a été assassinée sur le navire qui la transportait le jour de son déploiement."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "BORDER_ACT2_INTERLUDE6@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4500212
L30_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "잠깐. 한나 씨가 살해라니? 그게 무슨 소리죠?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ちょっと待ってください。ハンナさんが殺された？　それはどういうことですか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Wait a minute. Miss Anderson? Murdered? I don't understand."
L30_1.m_Talk_ENG = L31_1
L31_1 = "等等，你說漢娜遭人殺害竟？ 那是什麼意思？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เดี๋ยวนะคะ คุณฮันนาเหรอคะ? ถูกฆาตกรรมเหรอคะ? ฉันไม่เข้าใจค่ะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Chờ đã. Cô Hanna? Bị giết? Tôi không hiểu."
L30_1.m_Talk_VTN = L31_1
L31_1 = "等等，汉娜被杀害了？你这话是什么意思？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Warten Sie mal kurz. Frau Anderson? Ermordet? Ich verstehe nicht so ganz."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Attendez une minute. Mme Hanna? Assassinée ? Je ne comprends pas."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
