L32_1 = {}
L33_1 = "BORDER_ACT2_INTERLUDE6@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4500212
L32_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "WILBUR_NPC_FAKE_MASKED"
L32_1.m_CharStrID = L33_1
L33_1 = "저희 같은 청렴한 회사가 이런 사건에 휘말려 저도 무척 당황스럽습니다만…"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私共のような清廉な会社がこのような事件に巻き込まれて、僕としても非常に当惑しておりますが……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "We are ashamed that a company with our integrity was involved in such a horrific incident..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "像我們這種正當公司捲入這樣的事件中，我也感到很驚慌…"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เราละอายเหลือเกินครับที่บริษัทที่มีคุณธรรมอย่างเราต้องไปเกี่ยวข้องกับเหตุการณ์น่ากลัวแบบนี้..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Chúng tôi lấy làm xấu hổ khi một công ty với sự chính trực như chúng tôi lại dính líu đến một vụ việc khủng khiếp như vậy..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "像我们这样清廉诚实的公司被卷进这种事，我也感到很惶恐和惭愧。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wir schämen uns, dass ein Unternehmen mit unserer Integrität in einen so schrecklichen Vorfall verwickelt ist ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je suis navré qu'une entreprise aussi intègre que la nôtre ait été impliquée dans un drame aussi sordide..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "BORDER_ACT2_INTERLUDE6@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4500212
L33_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "WILBUR_NPC_FAKE_MASKED"
L33_1.m_CharStrID = L34_1
L34_1 = "부검 측에선 그녀의 사인이 익사가 아닌 총상으로 인한 과다출혈이라고 합니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "検死によれば彼女の死因は溺死ではなく、銃傷による出血過多だそうです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "However, according to the autopsy report, her cause of death was attributed to excessive bleeding from a gunshot wound, not drowning."
L33_1.m_Talk_ENG = L34_1
L34_1 = "法醫說，她的死因不是溺水，而是槍傷導致失血過多。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ยังไงก็ตาม จากรายงานการชันสูตร สาเหตุการตายของเธอเกิดจากการทนพิษบาดแผลถูกยิงไม่ไหวเพราะเสียเลือดมากเกินไปครับ ไม่ใช่จมน้ำ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tuy nhiên, theo báo cáo khám nghiệm tử thi, nguyên nhân cái chết của cô được cho là do chảy máu quá nhiều từ vết thương do đạn bắn chứ không phải chết đuối."
L33_1.m_Talk_VTN = L34_1
L34_1 = "尸检方说她的死因不是溺水，而是枪伤引起的失血过多。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Dem Autopsiebericht zufolge wurde ihre Todesursache jedoch auf übermäßige Blutung aus einer Schusswunde und nicht auf Ertrinken zurückgeführt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais le rapport d'autopsie est formel : son décès provient d'une hémorragie causée par balle, et non d'une noyade."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
