L36_1.m_fWaitTime = 0
L37_1 = "WILBUR_NPC_FAKE_MASKED"
L36_1.m_CharStrID = L37_1
L37_1 = "어쩌면 저희가 맺은 협업관계를 질투하는 악의적인 사보타주일지도 모르니, 앞으로도 다른 회사의 협업 제안은 조심하시는 편이…"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "もしかすると協業関係を嫉妬しての悪意的なサボタージュかもしれませんので、これからも他社からの協業提案にはお気をつけになった方が……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "We suspect a malicious saboteur from a competitor who is envious of our partnership. And we would advise caution when accepting a partnership agreement from another company..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "或許是有人眼紅我們合作而引發殺機，日後請小心其他公司的合作提議……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เราสงสัยว่าเป็นฝีมือนักก่อวินาศกรรมตัวร้ายจากบริษัทคู่แข่งที่อิจฉาเรา\nและเราขอแนะนำให้รับข้อตกลงการเป็นพันธมิตรจากบริษัทอื่นอย่างระมัดระวังนะครับ..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Chúng tôi nghi ngờ có kẻ ác ý phá hoại từ đối thủ cạnh tranh đang ghen tị với quan hệ đối tác của chúng ta. Và chúng tôi khuyên cô nên thận trọng khi chấp nhận thỏa thuận hợp tác từ một công ty khác..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "我方怀疑是嫉妒我们合作关系的竞争公司蓄意进行的破坏，也请您以后小心其他公司的合作提议……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wir vermuten einen böswilligen Saboteur eines Konkurrenten, der neidisch auf unsere Partnerschaft ist. Und wir raten zur Vorsicht, wenn Sie eine Partnerschaftsvereinbarung mit einem anderen Unternehmen annehmen ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Nous suivons actuellement la piste d'un sabotage déloyal de la part d'un de nos concurrents. Si vous comptez faire appel aux services d'une autre entreprise, nous vous conseillons d'user de prudence..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
