L37_1.m_CharStrID = L38_1
L38_1 = "…장교님? 듣고 계시나요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "……将校？　もしもし？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Officer Rashford...? Are you there?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "…軍官？你有在聽嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เจ้าหน้าที่แรชฟอร์ด...? ฟังอยู่รึเปล่าครับ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Sĩ quan Rashford...? Cô có ở đó không?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "……军官？您在听吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Offizierin Rashford ...? Sind Sie noch da?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Officier Rashford... ? Vous êtes encore avec moi ?"
L37_1.m_Talk_FRA = L38_1
