L39_1 = "나중에 다시 연락드리죠."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "後でまた連絡します。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I'll call you back later."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我晚點再跟你聯絡。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เดี๋ยวฉันโทรกลับนะคะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi sẽ gọi lại cho anh sau."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我以后再联系您。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich rufe Sie später zurück."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je vous rappelle plus tard."
