L43_1.m_Face = "UNIT_HATE"
L43_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "슈트를 입고 계시지 않은 모습은 오랜만이군요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "スーツを着ていない姿は久しぶりですね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It's been a while since I last saw you without your suit on."
L43_1.m_Talk_ENG = L44_1
L44_1 = "難得沒看你穿強化服。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันไม่ได้เห็นคุณไม่สวมชุดนั่นมาสักพักแล้วเหมือนกันนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Lâu lắm rồi tôi mới nhìn thấy cô không mặc bộ giáp."
L43_1.m_Talk_VTN = L44_1
L44_1 = "好久没看过你不穿强化服的样子了。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es ist schon eine Weile her, seit ich Sie das letzte Mal ohne Ihren Anzug gesehen habe."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Cela fait un moment que je ne vous avais pas vue sans votre combinaison."
L43_1.m_Talk_FRA = L44_1
