L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4500212
L45_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
