L46_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L45_1.m_StartFXSoundName = L46_1
L46_1 = "CYMBALS_NPC_NULL_HANNA"
L45_1.m_CharStrID = L46_1
L46_1 = "네, 이제 침식파 걱정은 하지 않아도 되니까요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "はい、もう侵食波を心配する必要はないですから。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Yes, with it I don't have to worry about the Corruption ray."
L45_1.m_Talk_ENG = L46_1
L46_1 = "對啊，現在不用再擔心侵蝕波了。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ค่ะ เพราะถ้าสวมไว้ฉันก็ไม่ต้องกลัวรังสีคอร์รัปชั่นนะคะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Vâng, với nó, tôi không phải lo lắng về Tia Ăn Mòn."
L45_1.m_Talk_VTN = L46_1
L46_1 = "是，因为现在我不用再担心侵蚀波了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich trage ihn ja, damit muss ich mir keine Sorgen um die Verderbniswellen machen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ah ? C'est vrai qu'avec la protection contre les Rayons de Corruption qu'elle offre, j'ai du mal à m'en passer."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "BORDER_ACT2_INTERLUDE6@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4500212
L46_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "계속 방에 계셨던 겁니까?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ずっとお部屋にいらしたんですか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Were you in your room this whole time?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你一直待在房間裡嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "นี่อยู่ในห้องตลอดเลยเหรอ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cô đã ở trong phòng suốt à?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "你一直待在房间里吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Waren Sie die ganze Zeit in Ihrem Zimmer?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Vous êtes restée dans votre chambre pendant tout ce temps ?"
L46_1.m_Talk_FRA = L47_1
