L49_1 = "BORDER_ACT2_INTERLUDE6@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4500212
L48_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "CYMBALS_NPC_NULL_HANNA"
L48_1.m_CharStrID = L49_1
L49_1 = "그럼요. 얌전히 기다리고 있었어요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "もちろんです。大人しく待ってたんですよ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Of course. I was waiting for you to come back."
L48_1.m_Talk_ENG = L49_1
L49_1 = "那當然，我一直乖乖地守著。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แน่สิคะ ฉันรอให้คุณกลับมาอยู่นี่นา"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tất nhiên. Tôi đang chờ cô trở lại mà."
L48_1.m_Talk_VTN = L49_1
L49_1 = "那当然。我正乖乖地等你回来呀。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Natürlich. Ich habe darauf gewartet, dass Sie zurückkommen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Bien entendu. J'attendais votre retour."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "BORDER_ACT2_INTERLUDE6@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4500212
L49_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "CYMBALS_NPC_NULL_HANNA"
L49_1.m_CharStrID = L50_1
L50_1 = "아무도 없는 사이에 누가 제 물건을 빼앗아가면 곤란하잖아요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "誰もいない間に、誰かが私のものを奪っていくと困るじゃないですか。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "It would be awkward if someone came in and took my things while no one was present, wouldn't it?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "要是有人趁沒人的時候，搶走我的東西那可就頭痛囉，你說是嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "มันคงน่าอึดอัดแย่ถ้ามีคนเข้ามาเอาของฉันไปตอนฉันไม่อยู่ ว่ามั้ยคะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Sẽ rất khó xử nếu ai đó vào và lấy đồ của tôi khi không có ai ở đây, phải không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "有谁趁着人不在的时候抢走我的东西不就麻烦了嘛？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Wäre es nicht unangenehm, wenn jemand mein Eigentum entwenden würde, während niemand da ist?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je ne voulais pas risquer de me faire dérober mes affaires pendant mon absence, vous comprenez ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "BORDER_ACT2_INTERLUDE6@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 4500212
L50_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_PRIDE"
L50_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "그 손에 들고 있는 게 네 물건이라고? 어이가 없군."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "その手に持っているものがお前のものだと？　呆れたな。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Are you saying that what you're holding in your hand right now belongs to you? This is ridiculous."
L50_1.m_Talk_ENG = L51_1
L51_1 = "你手裡拿著的是你的東西？真是無言。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "จะบอกว่าที่ถืออยู่นั่นเป็นของเธอเหรอ? ไร้สาระ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Cô đang nói thứ cô đang cầm trên tay là của cô sao? Điều này thật là buồn cười."
L50_1.m_Talk_VTN = L51_1
L51_1 = "你说什么？你手里拿的东西是你的？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wollen Sie damit sagen, dass Ihnen das, was Sie gerade in Ihrer Hand halten, Ihnen gehört? Das ist doch lächerlich."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Tes affaires ? Es-tu en train de me dire que cet objet t'appartient ? C'est ridicule."
L50_1.m_Talk_FRA = L51_1
