L2_1 = "넌 도대체 누구냐? 왜 한나 씨를 살해한 거지?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "お前はいったい誰だ？　なぜハンナさんを殺したんだ？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Who the hell are you? Why did you kill the real Hanna?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "你到底是誰？爲什麼要殺害漢娜？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แกเป็นใคร? ทำไมต้องฆ่าฮันนาด้วย?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cô là tên quái nào? Tại sao cô lại giết Hanna thật?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "你究竟是谁？为什么要杀害汉娜！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wer zur Hölle bist du? Warum hast du Frau Anderson umgebracht?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Qui es-tu ? Pourquoi as-tu tué la vraie Hanna ?"
