L3_1.m_Face = "UNIT_DESPAIR"
L4_1 = "THEMA_MAESTRO"
L3_1.m_StartBGMFileName = L4_1
L4_1 = "CYMBALS_NPC_NULL_HANNA"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "그런 말씀은 섭섭하네요. 당신과 3개월 동안 함께 정을 쌓아온 한나는 바로 저라고요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そんな言い方は寂しいですね。あなたと3カ月間親睦を深めてきたハンナは私の方なんですよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Your words are hurting me. I'm Hanna, the Hanna you've known and been together with for the past 3 months."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你怎麼這麼說，和你一起相處三個月的漢娜就是我。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แรงนะคะนั่น ฉันก็ฮันนาไงคะ ฮันนาที่คุณรู้จักแล้วก็อยู่ด้วยกันมาตลอด 3 เดือนนี้น่ะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Lời nói của cô đang làm tổn thương tôi đấy. Tôi là Hanna, cũng là Hanna mà cô đã biết và ở bên nhau trong 3 tháng qua mà."
L3_1.m_Talk_VTN = L4_1
L4_1 = "你这么说可真让人伤心啊。跟你相处3个月并积累了深厚友谊的人可是我。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ihre Worte verletzen mich. Ich bin Hanna Anderson, die Frau, die Sie kennen und die seit 3 ​​Monaten an Ihrer Seite ist."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vos paroles me font du mal. Je suis Hanna, la Hanna que vous avez connue et côtoyée pendant ces 3 derniers mois."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
