L8_1 = "BORDER_ACT2_INTERLUDE6@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500212
L7_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SERIOUS"
L7_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "날 속이고 여기까지 온 건, 그 성유물을 노린 거였나?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私を騙してここまで来たのは、その聖遺物を狙うためだったのか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You're after the Holy Relic. Isn’t that the reason why you deceived me and traveled all the way here?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你欺騙我到這裡來，是因為覬覦那個聖遺物嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แกจะมาเอาสิ่งตกทอดศักดิ์สิทธิ์ เพราะแบบนั้นเลยหลอกฉันแล้วก็เดินทางถึงนี่สินะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô đang theo đuổi Thánh Tích. Đó không phải là lý do tại sao cô lừa dối tôi và đi đến đây sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "欺骗我并来到这里，是因为觊觎那个圣遗物吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Du bist hinter dem Heiligen Artefakt her. Ist das nicht der Grund, warum du mich getäuscht hast und den ganzen Weg hierher gereist bist?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "C'est pour la Sainte Relique, que tu as voyagé jusqu'ici et que tu m'as trompée ?"
L7_1.m_Talk_FRA = L8_1
