L13_1 = "BORDER_ACT2_INTERLUDE6@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500212
L12_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_DESPAIR"
L13_1 = "CYMBALS_NPC_NULL_HANNA"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "R"
L13_1 = "아, 여러분이 목숨을 걸고 구해주신 <color=#ffd34c>이거</color> 말이죠?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あ、みなさんが命をかけて探してくれた<color=#ffd34c>これ</color>ですね？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Oh, you mean <color=#ffd34c>this thing</color> that you all risked your lives for?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你說大家冒著生命危險拿到的<color=#ffd34c>這個</color>嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อ๋อ หมายถึง<color=#ffd34c>ไอ้นี่</color>ที่เอาชีวิตไปเสี่ยงกันมานะเหรอ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ồ, ý cô là vì <color=#ffd34c>thứ này</color> mà tất cả các người đã liều mạng sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊，大家拼命找回来的<color=#ffd34c>这东西</color>吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ah, Sie meinen <color=#ffd34c>dieses Ding</color>, für das alle ihr Leben riskiert haben?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Oh, vous voulez dire... <color=#ffd34c>cette chose</color> pour laquelle vous avez tous risqué vos vies ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "BORDER_ACT2_INTERLUDE6@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500212
L13_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "CYMBALS_NPC_NULL_HANNA"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L14_1 = "이건 성유물이 아니라 악기랍니다. 가증스러운 엘리시움 녀석들에겐 심장과도 같은 힘의 원천이랄까요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "これは聖遺物じゃなくて楽器ですよ。憎いエリシウムのやつらには心臓のような力の源と言いますかね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "This isn't a Holy Relic, it's an instrument. A source of power, sort of what a heart would be to those despicable Elysium snobs."
L13_1.m_Talk_ENG = L14_1
L14_1 = "這不是聖遺物，這是樂器。這對可惡的愛樂組織來說，可以說是等同於心臟一般的力量來源呢。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นี่มันสิ่งตกทอดศักดิ์สิทธิ์ที่ไหนเล่า มันเครื่องดนตรีหรอก เป็นแหล่งพลังงาน แบบที่พวกเอลีเซียมหัวสูงน่ารังเกียจคิดว่าควรจะเป็นหัวใจน่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đây không phải là Thánh Tích, chỉ là một nhạc cụ. Một nguồn sức mạnh, đối với những kẻ hợm hĩnh Elysium đáng khinh mà nói giống như trái tim vậy."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这东西不是圣遗物，是乐器。对于乐团那些家伙来说，可以说是心脏一样的力量源泉吧？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Dies ist nicht das Heiliges Artefakt, es ist ein Instrument. Eine Kraftquelle, so etwas wie ein Herz für diese verabscheuungswürdigen Elysium-Snobs."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ce n'est pas une relique sacrée, c'est un instrument de musique. Une source de pouvoir qui sert de cœur à ces satanées snobs de l'Elysium."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "BORDER_ACT2_INTERLUDE6@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4500212
L14_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L15_1 = "L"
L14_1.m_Pos = L15_1
L15_1 = "그게 성유물이 아니라고? 무슨 헛소리지? 우린 분명 성유물의 시그니처 패턴을 추적했을 텐데?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "それが聖遺物ではないだと？　どういうことだ？　我々は確かに聖遺物のシグネチャーパターンを追跡したはずだが。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "It's not the Holy Relic? Nonsense! We tracked it down using the Holy Relic's signature pattern!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "那不是聖遺物嗎？你胡說什麼？我們明明有追蹤到聖遺物的信號模式？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ไม่ใช่สิ่งตกทอดศักดิ์สิทธิ์เหรอ? ไร้สาระ! เราตามหามันเจอด้วยรูปแบบเอกลักษณ์ของสิ่งตกทอดศักดิ์สิทธิ์นะ!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Không phải Thánh Tích sao? Vô lý! Chúng tôi đã lần ra nó bằng cách sử dụng tín hiệu đặc trưng của Thánh Tích!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "那个不是圣遗物？你在胡说八道什么？我们明明追踪到圣遗物的信号模式了？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Es ist nicht das Heilige Artefakt? Unsinn! Wir haben es anhand des Signaturmusters des Heiligen Artefakts aufgespürt!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ce n'est pas la Sainte Relique ? Balivernes ! C'est pourtant vers elle que le détecteur nous a menées !"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "BORDER_ACT2_INTERLUDE6@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4500212
L15_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_LAUGH"
L15_1.m_Face = L16_1
L16_1 = "CYMBALS_NPC_NULL_HANNA"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "R"
L16_1 = "후후, 아직도 그걸 믿고 있다니 귀여우셔라."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ふふ、まだそれを信じてるだなんて可愛らしい。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Fu fu. It’s so adorable that you still believe that."
L15_1.m_Talk_ENG = L16_1
L16_1 = "呵呵，你還相信那個喔？真可愛。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หุหุ น่าเอ็นดูจังที่ยังเชื่อแบบนั้นอยู่เนี่ย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Phu phu. Thật đáng yêu khi cô vẫn tin điều đó."
L15_1.m_Talk_VTN = L16_1
L16_1 = "呼呼，你到现在居然还相信那个，真可爱。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Haha. Es ist so süß, dass Sie das immer noch glauben."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Hu hu. Vous croyez encore cette histoire ? Comme c'est mignon."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "BORDER_ACT2_INTERLUDE6@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4500212
L16_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "CYMBALS_NPC_NULL_HANNA"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L17_1 = "시그니처 패턴이라는 건 완-전 뻥이었어요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "シグネチャーパターンってのは真っ赤な嘘でした。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The whole \"signature pattern\" thing was a COMPLETE lie!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "信號模式根本就是騙人的。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ไอ้ \"รูปแบบเอกลักษณ์\" อะไรนั่นมันเรื่องโกหกทั้งเพหรอกจ้า!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cái thứ \"tín hiệu đặc trưng\" đó HOÀN TOÀN là một lời nói dối!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "信号模式那东西完全是骗人的。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das „Signaturmuster“ war eine einzige Lüge!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Un détecteur permettant d'identifier l'emplacement de la Sainte Relique ? Ce n'était qu'un mensonge !"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "BORDER_ACT2_INTERLUDE6@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4500212
L17_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "CYMBALS_NPC_NULL_HANNA"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "정착자의 후손들이 성유물의 정체를 숨긴 덕분에 여러분의 절박한 마음을 이용할 수 있었죠."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "定着者の末裔が聖遺物の正体を隠してくれたおかげで、みなさんの切実な心を利用することができました。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Because the Settlers' descendants kept the true Holy Relic hidden from the rest of the world, I had no choice but to use everyone's desperation as leverage."
L17_1.m_Talk_ENG = L18_1
L18_1 = "因爲定居者的後裔掩藏聖遺物的真相，才能利用大家迫切的心。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ก็พวกลูกหลานของผู้ตั้งรกรากเอาสิ่งตกทอดศักดิ์สิทธิ์ของจริงไปซ่อนไว้ไม่ให้โลกรู้ ฉันเลยไม่มีทางเลือกอื่นนอกจากใช้ความสิ้นหวังของทุกคนให้เป็นประโยชน์ไงล่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bởi vì hậu duệ của Tiền Nhân đã che giấu Thánh Tích thực khỏi phần còn lại của thế giới, nên tôi không còn lựa chọn nào khác ngoài việc sử dụng sự tuyệt vọng của các người làm đòn bẩy."
L17_1.m_Talk_VTN = L18_1
L18_1 = "因为王室隐藏了圣遗物的真面目，我才能利用大家急切的心理。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Weil die Nachkommen der Siedler das wahre Heilige Artefakt vor dem Rest der Welt verborgen hielten, hatte ich keine andere Wahl, als die Verzweiflung aller als Druckmittel zu nutzen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Les descendants des Pionniers ayant gardé la Relique cachée du reste du monde, je n'avais pas d'autre choix que de plonger ce pays dans le désespoir le plus total pour espérer avoir des résultats."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "BORDER_ACT2_INTERLUDE6@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4500212
L18_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "CYMBALS_NPC_NULL_HANNA"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "그림자도 아니고 성유물의 시그니처 패턴이라는 게 정말로 존재할 리가 없잖아요?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "シャドウでもあるまいし、聖遺物のシグネチャーパターンなんて本当に存在してるわけないじゃないですか。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "A Holy Relic isn't a Shadow, so how can a signature pattern even exist?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "又不是暗影，聖遺物的信號模式怎麼可能真的存在？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "สิ่งตกทอดศักดิ์สิทธิ์ไม่ใช่แชโดว์ซะหน่อย แล้วจะไปมีรูปแบบเอกลักษณ์ได้ยังไง?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thánh Tích không phải là Cái Bóng, vậy thì làm sao mà một tín hiệu đặc trưng có thể tồn tại được?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "圣遗物又不是暗影，信号模式那种东西怎么可能真的存在？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ein Heiliges Artefakt ist kein Schatten. Wie kann ein Signaturmuster also überhaupt existieren?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "La Sainte Relique n'est pas une Ombre, enfin ! Comment pourrait-elle avoir une signature de corruption ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
