L20_1.m_Crash = 30
L21_1 = "성유물에 깃든 <color=#ffd34c>정령</color>을 고작 기계 따위로 감지할 수 있을 거라 믿다니. 머저리들."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "聖遺物に宿っている<color=#ffd34c>精霊</color>を、あんな機械なんかで感知できると信じるなんて。バカな人たち。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "So gullible of you all to truly believe that a machine can detect the <color=#ffd34c>Elemental</color> that dwells within the Holy Relic. Idiots."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你居然相信，光憑區區一台機器就能夠感應到聖遺物中蘊含的<color=#ffd34c>精靈</color>，真是好傻好天真。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "พวกเธอนี่ก็โง่จังน้อที่ไปเชื่อว่าเครื่องนั่นมันตรวจจับ<color=#ffd34c>ธาตุ</color>ที่อยู่ในสิ่งตกทอดศักดิ์สิทธิ์ได้ โง้โง่"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tất cả các người thật cả tin khi thực sự tin rằng một cỗ máy có thể phát hiện ra <color=#ffd34c>Nguyên tố</color> trú ngụ trong Thánh Tích. Đần độn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "居然相信用区区破机器就能检测到圣遗物中蕴含的<color=#ffd34c>精灵</color>，真是一群蠢货。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Zu glauben, dass der <color=#ffd34c>Geist</color>, der in dem Heiligen Artefakt wohnt, nur mit einer Maschine oder etwas anderem entdeckt werden kann. Was für Idioten ihr doch seid."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Vous pensez vraiment qu'une simple machine pourrait réagir à l'<color=#ffd34c>esprit</color> qui sommeille à l'intérieur ? Imbéciles."
L20_1.m_Talk_FRA = L21_1
