L25_1 = "BORDER_ACT2_INTERLUDE6@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4500212
L24_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_SURPRISE"
L24_1.m_Face = L25_1
L25_1 = "CYMBALS_NPC_NULL_HANNA"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "R"
L25_1 = "어머…? 죄, 죄송해요. 저도 모르게 못된 말이 나와버렸네요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あら……？　す、すみません。思わず悪口を言ってしまいました。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Oh...? I-I'm sorry... I didn't mean to blurt that out."
L24_1.m_Talk_ENG = L25_1
L25_1 = "哎呀……？對…對不起。不自覺就口出惡言。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "โอ๊ะ...? ทะ-โทษที... ไม่ได้ตั้งใจจะหลุดปากไปแบบนั้นนะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ồ...? T-tôi xin lỗi... Tôi không cố ý thốt ra điều đó."
L24_1.m_Talk_VTN = L25_1
L25_1 = "哦……哦哦？对、对不起。我无意间就说出了不好的话呢。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh ...? Es tut mir leid. Wie gemein von mir so etwas zu sagen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Oh...? M-Mes excuses, on dirait que ma langue a fourché..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "BORDER_ACT2_INTERLUDE6@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4500212
L25_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L26_1 = "CYMBALS_NPC_NULL_HANNA"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "R"
L26_1 = "힘을 얻으면서, 사악한 그림자 년의 기억과 성격도 조금 가져와버리고 말았거든요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "力を得る過程で、邪悪なシャドウ野郎の記憶と性格もちょっと持ってきちゃったんです。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "To become more powerful I had to let some of the vile Shadow's personality and memories inside."
L25_1.m_Talk_ENG = L26_1
L26_1 = "因為在獲得力量的同時，也取出一些邪惡暗影的記憶和性格。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เพื่อให้แข็งแกร่งกว่านี้ได้ ฉันก็ต้องยอมปล่อยให้นิสัยร้ายๆ ของแชโดว์กับความทรงจำข้างในออกมาบ้างน่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Để trở nên mạnh mẽ hơn, tôi phải để lại một số tính cách và ký ức thấp hèn của Cái Bóng bên trong."
L25_1.m_Talk_VTN = L26_1
L26_1 = "在获得力量的同时，也拿来了一点那个臭丫头的记忆和性格。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Um mächtiger zu werden, musste ich etwas von der Persönlichkeit und den Erinnerungen des abscheulichen Schattens in mich hineinlassen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Pour gagner en puissance, j'ai dû accepter une partie de la personnalité et des souvenirs de cette Ombre malveillante..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "BORDER_ACT2_INTERLUDE6@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4500212
L26_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_HATE"
L26_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L27_1 = "L"
L26_1.m_Pos = L27_1
L27_1 = "뭐가 됐든. 그걸 가지고 여길 빠져나갈 수 있을 거라 생각하진 마라."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "何はともあれ。それを持ってここから抜け出られると思うな。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Whatever. Don't you dare think for even a second that you'll be able to get out of here with that."
L26_1.m_Talk_ENG = L27_1
L27_1 = "不管如何，不要以爲你可以帶著它離開這裡。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "อะไรก็ช่าง คงไม่ได้แอบคิดว่านั่นจะทำให้รอดไปจากที่นี่ได้สินะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Sao cũng được. Cô đừng có nghĩ dù chỉ một giây rằng cô có thể ra khỏi đây với thứ đó."
L26_1.m_Talk_VTN = L27_1
L27_1 = "不管你是什么，你休想拿着那东西离开这里。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wie auch immer. Wage es nicht zu glauben, dass du damit hier rauskommst."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Peu importe ce que tu racontes. Tu ne crois quand même pas que je vais te laisser t'en tirer ainsi ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "BORDER_ACT2_INTERLUDE6@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4500212
L27_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L28_1 = "L"
L27_1.m_Pos = L28_1
L28_1 = "취조실에서 네 목적부터 숨기는 비밀까지 낱낱이 파헤쳐주마."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "取調室でお前の目的から隠している秘密まで全部暴いてやる。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I'm gonna lock you up in the interrogation room and extract your purpose and all your little secrets."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我會在審問室裡，將你的目的，甚至於是秘密都一一揭開。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันจะจับแกขังในห้องสอบปากคำ แล้วจะเค้นเอาจุดประสงค์แล้วก็ทุกความลับเล็กๆ ของแกออกมาให้หมด"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi sẽ nhốt cô trong phòng thẩm vấn và khai thác mục đích và tất cả những bí mật nhỏ của cô."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我会在审讯室一一揭开你的目的乃至你隐藏的秘密。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich werde dich im Verhörraum einsperren und dir deinen Zweck und all deine kleinen Geheimnisse entlocken."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je t'emmène à la salle d'interrogatoire. Ton objectif, tes petits secrets... tu vas tout nous dire."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "BORDER_ACT2_INTERLUDE6@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4500212
L28_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_DESPAIR"
L29_1 = "CYMBALS_NPC_NULL_HANNA"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "래시포드 씨, 저는 지금부터 성유물을 찾으러 갈 거예요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ラッシュフォードさん、私は今から聖遺物を探しに行きます。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Miss Rashford, I'm going to go retrieve the real Holy Relic now."
L28_1.m_Talk_ENG = L29_1
L29_1 = "雷斯福特，我現在要去找聖遺物。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "คุณแรชฟอร์ดค้า ฉันจะเอาสิ่งตกทอดศักดิ์สิทธิ์ไปแล้วนะค้า"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cô Rashford, bây giờ tôi sẽ đi lấy Thánh Tích thật."
L28_1.m_Talk_VTN = L29_1
L29_1 = "拉什福德，我接下来要去寻找真正的圣遗物了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Frau Rashford, ich werde mir jetzt das wahre Heilige Artefakt holen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ça ne va pas être possible, Mme Rashford. Car je vais aller récupérer la Sainte Relique, la vraie."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "BORDER_ACT2_INTERLUDE6@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4500212
L29_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L30_1 = "CYMBALS_NPC_NULL_HANNA"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L30_1 = "저희가 원했던 건 이 악기의 힘뿐이었지만, 마침 떠올라버렸거든요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私たちが欲しかったのはこの楽器の力だけでしたけど、ちょうど思い出しちゃいましたからね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "What we wanted was this instrument's powers, but I just remembered something."
L29_1.m_Talk_ENG = L30_1
L30_1 = "雖然我們想要的只是這個樂器的力量，但我正好想起來，"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ที่เราต้องการก็แค่พลังของเครื่องดนตรีนี่จ้า แต่ฉันเพิ่งนึกอะไรขึ้นมาได้ล่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Điều chúng tôi muốn là sức mạnh của món nhạc cụ này, nhưng tôi chợt nhớ ra một điều."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我们原本想要的只是这个乐器的力量而已，但我恰好想起来了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Was wir wollten, waren die Kräfte dieses Instruments, aber mir ist gerade etwas eingefallen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Au départ notre objectif était simplement de récupérer cet instrument, mais un souvenir vient de me revenir."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "BORDER_ACT2_INTERLUDE6@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4500212
L30_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "CYMBALS_NPC_NULL_HANNA"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "성유물을 운반하던 진짜 큐리안이 어디에 묻혀 있는지 말이예요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "聖遺物を運んでいた本物のキュリアンがどこに埋められているかを。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I know where the real Curian, the one who held onto the Holy Relic, is buried."
L30_1.m_Talk_ENG = L31_1
L31_1 = "搬運聖遺物的真正的庫里安埋在哪裡。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันรู้นะว่าคิวเรี่ยนตัวจริงที่ยึดมั่นในสิ่งตกทอดศักดิ์สิทธิ์นี่น่ะถูกฝังอยู่ที่ไหน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi biết nơi chôn cất Curian thực sự, người nắm giữ Thánh Tích."
L30_1.m_Talk_VTN = L31_1
L31_1 = "曾经负责运输圣遗物的那个真的奎里安被埋在了哪里。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich weiß, wo der echte Curian begraben ist, der das Heilige Artefakt besaß."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je sais où se trouve le corps du véritable Curian. Celui qui gardait la relique avec lui."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "BORDER_ACT2_INTERLUDE6@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4500212
