L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "하지만 떠나기 전에… 이 힘을 살짝 시험해봐야겠어요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "でも出発する前に……この力をちょっぴり試してみましょう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But before I go... I’ll have to see what this power can do."
L33_1.m_Talk_ENG = L34_1
L34_1 = "但是離開之前… 我得稍微試試這股力量。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ก่อนจะไป... ฉันคงต้องเห็นเป็นบุญตาหน่อยว่าพลังนี่ทำอะไรได้"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng trước khi tôi đi... tôi sẽ phải xem sức mạnh này có thể làm gì."
L33_1.m_Talk_VTN = L34_1
L34_1 = "不过在离开之前……就让我稍微试一下这个乐器的力量吧。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber bevor ich gehe ... muss ich diese Kraft einmal austesten."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais avant de partir... Voyons de quoi ce pouvoir est capable."
L33_1.m_Talk_FRA = L34_1
