L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "치, 침식체? 대체 언제 외성 안쪽까지 들어온 거지?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "し、侵食体？　いったいいつの間に外郭の中まで入ってきたんだ？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I-it's a C.O.! How did it get passed the wall?!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "侵…侵蝕體？是什麼時候進到外城的？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "วะ-วัตถุคอร์รัปต์! มันผ่านกำแพงเข้ามาได้ไงนี่?!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đ-đó là một V.T.A.M! Làm thế nào mà nó vượt qua được bức tường?!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "侵、侵蚀体？究竟是什么时候进到外城里面的？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "E-es ist ein C. O.! Wie ist es in die Außenburg gelangt?!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "U-Objet Corrompu ? Comment est-ce qu'il est entré ?!"
L40_1.m_Talk_FRA = L41_1
