L41_1.m_Pos = "R"
L42_1 = "위험해! 이대로는 주민들이 공격받고 말아!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "危ない！　このままでは住民が攻撃されるぞ！"
