L42_1 = "Look out! The villagers! They're in danger!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "危險！這樣下去居民們會受到攻擊的！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ระวังนะ! ชาวบ้านน่ะ! พวกเขากำลังตกอยู่ในอันตราย!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Coi chừng! Dân làng! Họ đang gặp nguy hiểm!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "危险！照这样下去，居民们会受到攻击的！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Achtung! Bei diesem Tempo werden die Bewohner bald angegriffen!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Merde, sonne l'alarme ! Le village est en danger !"
L41_1.m_Talk_FRA = L42_1
