L18_1 = "뭐? 여긴 이제 아무것도 없어. 대체 뭐가 있다는…"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "は？　もうここには何もいねえぞ。いったい何があるって……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "What? But there's nothing here. What are you talking ab─"
L17_1.m_Talk_ENG = L18_1
L18_1 = "什麼？這裡明明什麼都沒有，你到底在說什麼…"
L17_1.m_Talk_TWN = L18_1
L18_1 = "หา? ไม่เห็นมีไรเลยะน พูดอะไรของน–"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cái gì? Nhưng không có gì ở đây cả. Anh đang nói gì vậy-"
L17_1.m_Talk_VTN = L18_1
L18_1 = "什么？这里现在只有我们俩了，你到底……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Was? Aber hier ist doch nichts. Wovon zum Teufel redest du ─"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Quoi ? Je vois rien, moi. De quoi tu par─"
L17_1.m_Talk_FRA = L18_1
