L29_1 = "GUARD_BORDER_NULL_B"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "피하세요! 여긴 위험합니다! 침식체들이 외성 안으로 들어왔어요!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "避難してください！　ここは危険です！　侵食体が外郭の中に入ってきました！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "You need to get out of here! The C.O.s! They've made it inside the wall!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "快躲起來！這裡很危險！侵蝕體進到外城了！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "คุณต้องออกไปจากที่นี่นะครับ! วัตถุคอร์รัปต์ครับ! พวกมันเข้ามาในกำแพงได้แล้ว!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ông cần phải ra khỏi đây! V.T.A.M! Chúng đã vào được bên trong bức tường!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "快躲起来！这里危险！侵蚀体进到外城里面了！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Sie müssen hier weg! Die C.°O.s haben es in die Außenburg geschafft!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Vous devez évacuer ! Les Objets Corrompus ont pénétré à l'intérieur du fort !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
