L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "침식체가 어디 있다는 건가! 정신 차리게!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "侵食体がどこにいると言うんじゃ！　しっかりしなさい！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "What C.O.s?! Get your head straight!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "侵蝕體在哪裡？你清醒一點！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "วัตถุคอร์รัปต์ที่ไหนกัน?! ตั้งสติหน่อย!"
L29_1.m_Talk_THA = L30_1
L30_1 = "V.T.A.M nào?! Tỉnh táo lại đi!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "侵蚀体在哪儿呢！你清醒点！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Welche C.°O.s?! Ich sehe keine! Reiß dich zusammen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "De quoi tu parles ? Ressaisis-toi, bon sang !"
L29_1.m_Talk_FRA = L30_1
