L30_1.m_Pos = "C"
L31_1 = "아닙니다! 여길 보시면 저희가 벌써 두 마리나…"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "違います！　ここを見てください、俺らがもう二匹も……"
