L31_1 = "I-I'm telling you the truth! See? I've already killed─"
L30_1.m_Talk_ENG = L31_1
L31_1 = "不！你看，我們已經殺掉二隻…"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผะ-ผมพูดความจริงนะครับ! เห็นมั้ย? เราเพิ่งฆ่า–"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi đang nói với ông sự thật! Nhìn đi? Tôi đã giết-"
L30_1.m_Talk_VTN = L31_1
L31_1 = "不是的！你看这里，我们已经杀死两只了……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich sage die Wahrheit! Sehen Sie mal hier, ich habe bereits zwei getötet ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais je vous dis la vérité ! Regardez, je viens d'en abattre de─"
L30_1.m_Talk_FRA = L31_1
