L35_1 = "죄송합니다, 촌장님… 저 같은 살인자는 죽어야 해요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "すみません、村長……俺のような殺人犯は死ぬべきです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I'm sorry, Chief... A murderer like me doesn't deserve to live."
L34_1.m_Talk_ENG = L35_1
L35_1 = "對不起，村長…像我這樣的殺人犯必須要死。"
L34_1.m_Talk_TWN = L35_1
