L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi xin lỗi, Trưởng làng... Một kẻ sát nhân như tôi không đáng được sống."
L34_1.m_Talk_VTN = L35_1
L35_1 = "对不起，村长……我是……杀人凶手。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Es tut mir leid, Herr O‘Neill ... Ein Mörder wie ich verdient es nicht zu leben."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je... je suis désolé, chef... un meurtrier comme moi ne mérite pas de vivre."
L34_1.m_Talk_FRA = L35_1
