L3_1 = "BORDER_ACT2_INTERLUDE6@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4500212
L2_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_DESPAIR"
L3_1 = "CYMBALS_NPC_NULL_HANNA"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "음악으로 기적을 전파하는 거예요, 래시포드 씨."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "音楽で奇跡を広めてるんですよ、ラッシュフォードさん。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I just caused a miracle through music, Miss Rashford."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我在用音樂傳播奇蹟，雷斯福特。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฉันก็แค่ใช้ดนตรีสร้างปฏิหาริย์เองน้า คุณแรชฟอร์ด"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi vừa tạo ra phép màu nhờ âm nhạc, cô Rashford."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我在用音乐传播奇迹，拉什福德。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich habe gerade durch Musik ein Wunder bewirkt, Frau Rashford."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Je viens de créer un miracle musical, Mme Rashford."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "BORDER_ACT2_INTERLUDE6@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4500212
L3_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "CYMBALS_NPC_NULL_HANNA"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "실존하지 않는 행복도, 슬픔도, 두려움도…"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "実存しない幸せも、悲しみも、恐怖も……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "All the happiness, sorrow, and fear that doesn't exist..."
L3_1.m_Talk_ENG = L4_1
L4_1 = "不存在的幸福、悲傷、恐懼… "
L3_1.m_Talk_TWN = L4_1
L4_1 = "ทุกความสุข ความเศร้า และความกลัวที่ไม่มีตัวตน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tất cả hạnh phúc, đau khổ và sợ hãi đều không tồn tại..."
L3_1.m_Talk_VTN = L4_1
L4_1 = "并不真实存在的幸福，悲伤，恐惧……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "All das Glück, die Trauer und die Angst, die es nicht gibt ..."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Le bonheur, le chagrin, la peur... toutes ces choses ne sont que des illusions."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "BORDER_ACT2_INTERLUDE6@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4500212
L4_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "CYMBALS_NPC_NULL_HANNA"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "귀를 울리는 선율만으로 얼마든지 느낄 수 있거든요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "耳を打つ旋律だけでいくらでも感じることができるんです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You can feel it if you just listen carefully to the melody."
L4_1.m_Talk_ENG = L5_1
L5_1 = "只要用震耳的旋律就能感受到。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ถ้าตั้งใจฟังท่วงทำนองให้ดีๆ ก็จะสัมผัสได้นะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô có thể cảm nhận được điều đó nếu cô lắng nghe kỹ giai điệu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "只需通过回响在耳边的旋律，就全都能感受到。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie können sie allein durch die klingende Melodie in Ihren Ohren spüren."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Vous pourrez le sentir si vous écoutez attentivement cette mélodie."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "BORDER_ACT2_INTERLUDE6@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4500212
L5_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_LAUGH"
L5_1.m_Face = L6_1
L6_1 = "CYMBALS_NPC_NULL_HANNA"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "…하지만 어째서일까요. 이 능력을 쓰니 제 자신이 점점 잊혀지는 느낌이에요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……でもどうしてでしょう。この能力を使うと、段々私自身が消えていくような感じがします。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But there’s something strange... The more I use my powers, the more I feel like I'm losing myself."
L5_1.m_Talk_ENG = L6_1
L6_1 = "…但爲什麼會這樣呢？使用這個能力後，卻感覺自己越來越被遺忘。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่มีอะไรแปลกๆ แฮะ... ทำไมยิ่งใช้พลังก็ยิ่งรู้สึกเหมือนคุมตัวเองไม่ได้เนี่ย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng có một điều kỳ lạ... Càng sử dụng sức mạnh của mình, tôi càng cảm thấy mình đang đánh mất chính mình."
L5_1.m_Talk_VTN = L6_1
L6_1 = "……不过为什么……使用了这个能力后，我好像要忘记自己是谁了……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber es ist etwas seltsam ... Je mehr ich meine Kräfte nutze, desto mehr habe ich das Gefühl, dass ich mich selbst verliere."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais c'est étrange... plus j'utilise ce pouvoir, plus celui-ci semble me consumer..."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "BORDER_ACT2_INTERLUDE6@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4500212
L6_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_SURPRISE"
L6_1.m_Face = L7_1
L7_1 = "CYMBALS_NPC_NULL_HANNA"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L6_1.m_Crash = 20
L7_1 = "래, 래시포드 씨? 저요. 저 눈이 너무 아픈데, 거울이 없어서요. 제가 지금 어떻게 되어가고 있는 거죠?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ら、ラッシュフォードさん？　私ね。私、目がめちゃくちゃ痛いんですけど、鏡がなくて。今の私、どうなってるんですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "M-Miss Rashford...? Do you happen to have a mirror? My eyes really hurt. What's happening to me?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "雷…雷斯福特？我…我的眼睛好痛，沒有鏡子，我現在變成什麼樣子？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "คะ-คุณแรชฟอร์ดคะ...? คุณพอจะบังเอิญมีกระจกมั้ยคะ? ฉันเจ็บตาจังเลยค่ะ ฉันเป็นอะไรไปคะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "C-cô Rashford...? Cô có gương không? Mắt tôi thực sự đau. Chuyện gì đang xảy ra với tôi?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "拉、拉什福德？我，我的眼睛太疼了，你有没有镜子……可不可以告诉我……我现在变成什么样子了？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "F-Frau Rashford? Haben Sie zufällig einen Spiegel? Meine Augen tun wirklich weh. Was passiert mit mir?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "M-Mme Rashford ? V-Vous n'auriez pas un miroir ? Mes yeux, mes yeux me font si mal... qu'est-ce qui m'arrive ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "BORDER_ACT2_INTERLUDE6@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4500212
