L7_1.m_Face = "UNIT_HATE"
L7_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Crash = 20
L8_1 = "…완전히 미쳤군."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "……完全にいかれてるな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "…Completely insane."
L7_1.m_Talk_ENG = L8_1
L8_1 = "…你這個瘋子。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แกมันบ้าไปแล้วจริงๆ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô đã hoàn toàn mất trí."
L7_1.m_Talk_VTN = L8_1
L8_1 = "……你完全疯了啊。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "… Du hast wohl komplett den Verstand verloren."
L7_1.m_Talk_DEU = L8_1
L8_1 = "... Elle est complètement folle."
L7_1.m_Talk_FRA = L8_1
