L9_1 = "BORDER_ACT2_INTERLUDE6@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4500212
L8_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_SURPRISE"
L8_1.m_Face = L9_1
L9_1 = "CYMBALS_NPC_NULL_HANNA"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L8_1.m_Crash = 20
L9_1 = "아아… 아파… 난 힘을 얻었는데, 어째서 이렇게 아픈 걸까요?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ああ……痛い……力を手に入れたのに、どうしてこんなにも痛いんでしょう？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Ahh... It hurts... I'm so powerful, but why does it hurt so much?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "啊啊…好痛…我明明是得到力量，怎麼會這麼痛？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อ๊า... เจ็บจัง... ฉันแข็งแกร่งจะแย่ แต่ทำไมมันเจ็บจะตายแบบนี้ล่ะ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ahh... Đau quá... Tôi mạnh mẽ như vậy, nhưng tại sao lại đau đến vậy?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "啊啊……好痛……我获得了如此强大的力量，但为什么会这么痛呢？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ahh ... Es tut weh ... Ich bin so mächtig, aber warum tut es nur so weh?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ahh... quelle douleur atroce... Le pouvoir est à moi, alors pourquoi j'ai si mal ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "BORDER_ACT2_INTERLUDE6@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500212
L9_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "CYMBALS_NPC_NULL_HANNA"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "시커먼 속삭임이 들려요. 무, 무서워요. 저 좀 도와주세요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "真っ黒なささやきが聞こえます。こ、怖い。助けてください。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I hear dark whispers... I-I'm scared... Please, help me...!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "能聽到漆黑的低語，好害怕，請幫幫我。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันได้ยินเสียงกระซิบจากความมืด... ฉะ-ฉันกลัวจัง... ช่วยฉันด้วยค่ะ...!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi nghe thấy những lời thì thầm đen tối... Tôi sợ hãi... Làm ơn, hãy giúp tôi...!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "我能听到黑暗中传来的低语，好、好可怕。请帮帮我。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich höre ein dunkles Flüstern. O-oh, ich habe solche Angst! Bitte helfen Sie mir!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Et ces voix sombres qui me chuchotent à l'oreille... j'ai peur ... s'il vous plaît, aidez-moi... !"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "BORDER_ACT2_INTERLUDE6@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4500212
L10_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L11_1 = "CYMBALS_NPC_NULL_HANNA"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "래시포드 씨의 살점을 도려내면 조금 진정이 될 것 같은데… 도와주실 거죠?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ラッシュフォードさんの肌をえぐり取ればちょっとは落ち着くかも……助けてくれますよね？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I think... It would calm me down if you let me carve out some your skin, Miss Rashford... Will you please let me?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "若是割一點雷斯福特的肉下來，應該能鎮定一些…你會幫我吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฉันว่า... ใจฉันคงสงบลงได้ถ้าคุณยอมให้ถลกหนังออกสักหน่อย คุณแรชฟอร์ดคะ... ให้ฉันถลกหนังคุณได้มั้ยคะ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi nghĩ... Tôi sẽ bình tĩnh lại nếu cô để tôi rạch da cô một chút, cô Rashford... Làm ơn đi?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "是、是么……只要剜掉她的肉，我就能冷静一点了……拉什福德，你会帮我的吧？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich denke ... Es würde mich beruhigen, wenn Sie mir erlauben würden, etwas von Ihrer Haut herauszuschneiden, Frau Rashford ... Dürfte ich das bitte tun?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je crois que... ça me calmerait un peu si vous me laissiez vous couper les veines, Mme Rashford. Vous allez m'aider, n'est-ce pas ?"
L10_1.m_Talk_FRA = L11_1
