L19_1 = "ELLA_BORDER_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "방금 그 불길한 소리를 낸 게 너였나?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "さっき、あの不吉な音を出したのはあなたなのか？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Are you the one who made that disturbing noise?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "剛才那個倒霉的聲音是你嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แกเองเหรอที่ทำเสียงน่ารำคาญนั่น?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Cô à người đã gây ra tiếng ồn đáng ngại đó à?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "刚才发出那个不详声音的是你吗？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Bist du diejenige, die dieses störende Geräusch gemacht hat?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "C'est toi qui fait ce bruit bizarre ?"
L18_1.m_Talk_FRA = L19_1
