L21_1 = "ELLA_BORDER_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "물러서시죠. 여긴 제가 맡겠습니다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "下がっていてください。ここは私が引き受けましょう。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Step away. I’ll handle her."
L20_1.m_Talk_ENG = L21_1
L21_1 = "請退下，這裡我來負責。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ถอยไปค่ะ ฉันจะจัดการเธอเอง"
L20_1.m_Talk_THA = L21_1
L21_1 = "Lùi lại đi. Tôi sẽ xử lý cô ta."
L20_1.m_Talk_VTN = L21_1
L21_1 = "请退后，这里交给我。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Treten Sie zurück. Ich kümmere mich um sie."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Éloignez-vous, je vais m'occuper d'elle."
