L23_1 = "CYMBALS_NPC_NULL_HANNA"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "아아… 안녕하세요, 대장님?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ああ……どうも、隊長。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Aah... Hello, Captain."
L22_1.m_Talk_ENG = L23_1
L23_1 = "啊啊… 隊長你好？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เอ๊า... หวัดดีค่า หัวหน้า"
L22_1.m_Talk_THA = L23_1
L23_1 = "Aah... Xin chào, Đội trưởng."
L22_1.m_Talk_VTN = L23_1
L23_1 = "啊、啊……你好，队长？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ahh ... Hallo, Kommandantin."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Aah... Bonjour, capitaine."
