L24_1 = "BORDER_ACT2_INTERLUDE6@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4500212
L23_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "CYMBALS_NPC_NULL_HANNA"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "제 연주를 듣고 여기까지 난입하신 건가요? 관중매너가 영 꽝이네요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "私の演奏を聞いてここまで乱入してきたんですか？　マナーがまったくなっていませんね。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Did you barge in here after listening to my performance? My, your concert etiquette is awful."
L23_1.m_Talk_ENG = L24_1
L24_1 = "是聽到我的演奏後，隨意闖入這裡嗎？觀衆真沒禮貌。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "นี่คุณพรวดพราดมาดูการแสดงของฉันเหรอคะเนี่ย? มารยาทการไปคอนเสิร์ตแย่จังนะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô xông vào đây sau khi nghe màn biểu diễn của tôi à? Trời ạ, phép lịch sự của cô tệ quá."
L23_1.m_Talk_VTN = L24_1
L24_1 = "你听到了我的演奏，还擅闯进来吗？真是没礼貌的观众。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Sind Sie den ganzen Weg hierher gekommen, nachdem Sie meinen Auftritt gehört hatten? Ihre Manieren lassen wirklich zu wünschen übrig."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Vous êtes venue me saluer pour ma performance ? Mais je n'ai pas encore fini enfin, où sont vos manières ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "BORDER_ACT2_INTERLUDE6@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4500212
L24_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "ELLA_BORDER_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "넌… 그림자군."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あなたは……シャドウだな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You... you’re a Shadow."
L24_1.m_Talk_ENG = L25_1
L25_1 = "原來你是… 暗影。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แก... แกคือแชโดว์สินะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cô... cô là một Cái Bóng."
L24_1.m_Talk_VTN = L25_1
L25_1 = "原来……你是暗影。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du ... bist also ein Schatten."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Toi... Tu es une Ombre, n'est-ce pas ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "BORDER_ACT2_INTERLUDE6@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4500212
L25_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_PRIDE"
L26_1 = "CYMBALS_NPC_NULL_HANNA"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L25_1.m_Crash = 30
L26_1 = "아하하하! 그림자라는 것도 아세요? 못 배운 외성 출신치곤 똑똑하시네요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あははは！　シャドウのことも知ってるんですか？　学歴のない外郭出身にしては頭がいいですね。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Ah hah hah hah! You know about Shadows too? And here I thought you were just some bumpkin!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "哈哈哈！你連暗影都知嗎道？明明來自沒什麼學問的外城，還算蠻聰明的嘛。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "อะฮ่าฮ่าฮ่า! รู้จักแชโดว์ด้วยเหรอเนี่ย? แหม เห็นอยู่ที่นี่ไอ้เราก็นึกว่าเป็นพวกบ้านนอกธรรมดาซะอีก!"
L25_1.m_Talk_THA = L26_1
L26_1 = "A ha ha ha! Cô cũng biết về Cái Bóng à? Vậy mà tôi cứ nghĩ cô chỉ là đứa tiểu tốt!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "啊哈哈哈！你还知道暗影？虽然是没学过什么的外城出身，但很聪明啊。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ahahaha! Sie kennen also Schatten? Für eine ungebildete Außenburgbewohnerin sind Sie doch recht schlau."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Bwa ha ha ha ! Alors tu connais aussi les Ombres ? Pour une fille de la campagne, tu as de la culture !"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "BORDER_ACT2_INTERLUDE6@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4500212
L26_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "ELLA_BORDER_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "요리를 하는 사람은, 후각이 예민하거든."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "料理をする人は、匂いに敏感なんだ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Chefs tend to have a keen sense of smell."
L26_1.m_Talk_ENG = L27_1
L27_1 = "做菜的人，嗅覺很敏銳。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คนทำอาหารมักจะจมูกดีกันน่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Các đầu bếp thường có khứu giác nhạy bén."
L26_1.m_Talk_VTN = L27_1
L27_1 = "会做菜的人嗅觉可是很敏锐的。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Köche neigen dazu, einen ausgeprägten Geruchssinn zu haben."
L26_1.m_Talk_DEU = L27_1
L27_1 = "À force de passer du temps en cuisine, j'ai fini par avoir un odorat développé."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "BORDER_ACT2_INTERLUDE6@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4500212
L27_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ELLA_BORDER_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "특히 너처럼 더러운 피를 가진 침식체라면 말이지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "特にお前のように汚い血が流れている侵食体ならな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Especially if it's a C.O. with tainted blood like you."
L27_1.m_Talk_ENG = L28_1
L28_1 = "尤其是像你這種有著骯髒血液的侵蝕體。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "โดยเฉพาะถ้ามันเป็นวัตถุคอร์รัปต์เลือดปนเปื้อนอย่างแก"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đặc biệt nếu đó là V.T.A.M với dòng máu nhiễm độc như cô."
L27_1.m_Talk_VTN = L28_1
L28_1 = "尤其是像你这样流着肮脏血液的侵蚀体，一闻就闻得出来。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Vor allem, wenn es sich um ein dreckiges C. O. wie dich handelt."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Un O.C. avec du sang corrompu comme toi, je peux le sentir à des kilomètres."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "BORDER_ACT2_INTERLUDE6@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4500212
L28_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_HATE"
L29_1 = "CYMBALS_NPC_NULL_HANNA"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "틀렸어요. 전 그저 그림자의 힘을 이용하고 있는 것뿐이거든요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "違います。私はただシャドウの力を利用してるだけですからね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Wrong. I'm just using the powers of a Shadow."
L28_1.m_Talk_ENG = L29_1
L29_1 = "不對，我只是在利用暗影的力量而已。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ผิดจ้า ฉันแค่กำลังใช้พลังของแชโดว์ต่างหาก"
L28_1.m_Talk_THA = L29_1
L29_1 = "Sai rồi. Tôi chỉ đang sử dụng sức mạnh của một Cái Bóng."
L28_1.m_Talk_VTN = L29_1
L29_1 = "你错了。我只是在利用暗影的力量而已。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Sie liegen falsch. Ich nutze nur die Kräfte eines Schattens."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Faux. Je ne suis pas une Ombre, j'en utilise simplement les pouvoirs."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "BORDER_ACT2_INTERLUDE6@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4500212
L29_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L30_1 = "CYMBALS_NPC_NULL_HANNA"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "그리고 마침 당신 같은 카운터가 나타나줬으니, 이 힘을 시험해 봐야겠어요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "それに、ちょうどあなたのようなカウンターが現れたんですから、この力を試してみないと。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "But since a Counter appeared in front of me, it shouldn’t let this opportunity pass and try out my new powers."
L29_1.m_Talk_ENG = L30_1
L30_1 = "現在正好有你這樣的制裁者出現，那我得試試這股力量。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แต่ไหนๆ เคาน์เตอร์ก็โผล่มาตรงหน้าแล้ว ก็ไม่น่าปล่อยโอกาสลองพลังใหม่หลุดมือไปนี่น้อ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhưng vì một Counter xuất hiện trước mặt tôi, tôi không nên bỏ qua cơ hội này và thử sức mạnh mới của mình."
L29_1.m_Talk_VTN = L30_1
L30_1 = "正好，有你这样的制裁者出现，那就让我再多试一点点吧？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Und da gerade ein Counter wie Sie aufgetaucht ist, muss ich diese Kraft testen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Maintenant que j'ai une Counter devant les yeux, je ne peux pas laisser passer cette chance. C'est l'heure de la démonstration !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
