L35_1 = "BORDER_ACT2_INTERLUDE6@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4500212
L34_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "CYMBALS_NPC_NULL_HANNA"
L34_1.m_CharStrID = L35_1
L35_1 = "와아, 정말로 내 공격이 통했어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "わあ、本当に私の攻撃が通じたんだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Wow... I can't believe my attack really worked."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哇，我的攻擊真的有效。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "โห... ไม่อยากเชื่อว่าการโจมตีของฉันจะได้ผลจริงๆ นะเนี่ย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Wow... Tôi không thể tin rằng đòn tấn công của tôi thực sự hiệu quả."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哇，我的攻击真的管用啊。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wow! Ich kann nicht glauben, dass mein Angriff wirklich funktioniert hat."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ouah... Je n'arrive pas à croire que cette attaque a vraiment fonctionné."
L34_1.m_Talk_FRA = L35_1
