L36_1 = "BORDER_ACT2_INTERLUDE6@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4500212
L35_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_IDLE"
L36_1 = "CYMBALS_NPC_NULL_HANNA"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "이 힘이라면 정말로… 펠릭스 님 말씀처럼 관리국에 복수할 수 있을지도 몰라."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "この力なら本当に……フェリックス様が言ったとおり、管理局に復讐することができるかもしれない。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "With this power... We might be able to get revenge on the Administration, just like Mr. Felix said."
L35_1.m_Talk_ENG = L36_1
L36_1 = "有股力量後…或許就像菲利克斯先生說的，我可以向管理局報仇。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ถ้ามีพลังนี้ละก็... เราอาจล้างแค้นองค์การบริหารโลกได้อย่างที่คุณเฟลิกซ์ว่านะเนี่ย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Với sức mạnh này... Chúng tôi có thể trả thù Cục Quản Lý, giống như ông Felix đã nói."
L35_1.m_Talk_VTN = L36_1
L36_1 = "有了这股力量……说不定真能像菲利克斯阁下说的那样向管理局复仇。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Mit dieser Macht ... könnten wir uns vielleicht an der Administration rächen, genau wie Felix es gesagt hat."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Felix avait raison... avec une telle force, on pourra enfin se venger de l'Administration."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
