L45_1.m_Talk_THA = L46_1
L46_1 = "Cô tưởng một khẩu súng sẽ giết được tôi sao? Cô thật đáng yêu, cô Rashford."
L45_1.m_Talk_VTN = L46_1
L46_1 = "你想用那把破手枪杀死我吗？拉什福德！你真是太可爱了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Sie denken, dass eine Waffe mich töten wird? Sie sind wirklich so süß, Frau Rashford."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous croyez vraiment pouvoir me tuer avec ce jouer ? Vous êtes tellement adorable, Mme Rashford."
L45_1.m_Talk_FRA = L46_1
