L17_1 = "BORDER_ACT2_INTERLUDE6@266#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4500212
L16_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_SURPRISE"
L16_1.m_Face = L17_1
L17_1 = "CYMBALS_NPC_NULL_HANNA"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "앗, 미안해요. 힘조절을 잘못했나? 죽일 생각은 없었는데."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あっ、ごめんなさい。力加減を間違っちゃったのかな？　殺す気はなかったのに。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oops, sorry! Didn't mean to hit you so hard and kill you."
L16_1.m_Talk_ENG = L17_1
L17_1 = "對不起，是我沒拿捏力量嗎？我沒有想要殺她的意思。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อุ๊ ขอโทษนะ! ไม่ได้กะจะเอาถึงตายเลยอะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ối xin lỗi! Không có ý đánh cô quá mạnh. Tôi không có ý giết cô đâu."
L16_1.m_Talk_VTN = L17_1
L17_1 = "啊，抱歉。是没掌控力度吗？我没想杀死她的。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ups, tut mir leid! Ich hatte wirklich nicht vor, Sie zu töten."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ah, désolée ! J'ai encore du mal à contrôler ma force, je ne voulais pas te tuer !"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "BORDER_ACT2_INTERLUDE6@267#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 267
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4500212
L17_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "CYMBALS_NPC_NULL_HANNA"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L17_1.m_Crash = 20
L18_1 = "근데 이거…"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "でも、これ……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "But this..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "不過，這是…"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แต่มันก็..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Nhưng thứ này..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "不过这样……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Aber es ..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "En revanche..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "BORDER_ACT2_INTERLUDE6@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4500212
L18_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_SERIOUS"
L19_1 = "CYMBALS_NPC_NULL_HANNA"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "…엄청 기분 좋네요. 그 배에서 연구원을 죽였을 땐 정말 끔찍한 기분이었는데 말이예요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "……めっちゃ気持ちいいですね。あの船で研究員を殺した時には本当に最悪な気分でしたけど。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "This feels great! It's weird because I felt horrible for killing that researcher on the boat last time."
L18_1.m_Talk_ENG = L19_1
L19_1 = "…心情好好喔。在那艘船上殺死研究員的時候，感覺真的很可怕。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ดีต่อใจไม่ไหวแล้ว! แปลกจังนะเนี่ย คราวก่อนตอนฆ่านักวิจัยคนนั้นบนเรือนี่อี๋มาก"
L18_1.m_Talk_THA = L19_1
L19_1 = "Cảm giác thật tuyệt vời! Thật kỳ lạ vì tôi cảm thấy tệ vì đã giết nhà nghiên cứu trên cái thuyền đó."
L18_1.m_Talk_VTN = L19_1
L19_1 = "……心情真的很好。在船上杀死那个研究员时，我的心情还很糟糕呢。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Es fühlt sich großartig an! Es ist seltsam, weil ich mich schrecklich gefühlt habe, als ich diese Forscherin auf dem Boot getötet habe."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Ça fait un bien fou ! C'est bizarre... quand j'ai tué cette chercheuse sur ce bateau la dernière fois, j'étais rongée par le remords..."
L18_1.m_Talk_FRA = L19_1
