L21_1 = "BORDER_ACT2_INTERLUDE6@270#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4500212
L20_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_LAUGH"
L20_1.m_Face = L21_1
L21_1 = "CYMBALS_NPC_NULL_HANNA"
L20_1.m_CharStrID = L21_1
L21_1 = "L_F_C"
L20_1.m_Pos = L21_1
L21_1 = "래시포드 씨. 이제 당신 차례예요. 래시포드 씨도 필사적으로 저항하실 거죠?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ラッシュフォードさん。今度はあなたの番ですよ。ラッシュフォードさんも必死に抗うつもりなんでしょう？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Miss Rashford, it's your turn now. You're going to fight for your life too, right?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "雷斯福特，現在輪到你，你也會拼命抵抗吧？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คณแรชฟอร์ด ตาคุณละน้า คุณก็จะสู้เพื่อเอาชีวิตรอดเหมือนกันใช่มั้ยค้า?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô Rashford, giờ đến lượt cô. Cô cũng sẽ liều chết chiến đấu chứ?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "拉什福德，接下来轮到你了。拉什福德也会拼死抵抗的吧？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Frau Rashford, jetzt sind Sie an der Reihe. Sie werden auch um Ihr Leben kämpfen, oder?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Mme Rashford, c'est à votre tour maintenant. Vous allez me faire le plaisir de vous battre pour votre vie, d'accord ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "BORDER_ACT2_INTERLUDE6@271#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 271
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4500212
L21_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "CYMBALS_NPC_NULL_HANNA"
L21_1.m_CharStrID = L22_1
L22_1 = "L"
L21_1.m_Pos = L22_1
L22_1 = "발톱부터 하나 하나 천천히, 제가 연주해드려도 될까요?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "足の爪からひとつひとつゆっくり、演奏してあげてもいいですか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "So how about I gradually tune you, beginning with your toes?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "從腳趾甲開始一個一個慢慢地，我可以幫你演奏嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "งั้นฉันค่อยๆ ตั้งเสียงคุณดีมั้ยน้อ เริ่มจากหัวแม่เท้าเป็นไง?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Vì vậy, sẽ ra sao nếu tôi diễn tấu cô dần dần, bắt đầu từ ngón chân nhé?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "我可以先从脚指甲开始，一个、一个地慢慢演奏吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wie wäre es also, wenn ich Sie schrittweise stimmen würde, beginnend mit Ihren Zehen?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Et si on prenait notre temps, cette fois-ci ? Je vais commencer par couper vos orteils, l'un après l'autre..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "BORDER_ACT2_INTERLUDE6@272#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 272
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4500212
L22_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_HATE"
L22_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Crash = 20
L23_1 = "미친 자식. 네놈의 장난감이 될 바엔…"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "狂ってる。貴様のおもちゃになるなら……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "You're insane. I’d rather die than become your toy."
L22_1.m_Talk_ENG = L23_1
L23_1 = "瘋子，與其成爲你的玩具…"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แกมันบ้าชัดๆ ฉันยอมตายดีกว่าต้องเป็นของเล่นของแกเถอะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cô điên rồi. Tôi thà chết chứ không trở thành đồ chơi của cô."
L22_1.m_Talk_VTN = L23_1
L23_1 = "你这个疯子，与其成为你这家伙的玩具……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Du bist doch verrückt. Ich würde lieber sterben, als dein Spielzeug zu werden."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Je préfère encore mourir que de te servir de jouet, espèce de maniaque."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
