L38_1[L39_1] = L40_1
L39_1 = "…지휘관? 어떻게 여기로 온 거지?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "……指揮官？　どうやってここへ？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Commander? How did you know I was here?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "…指揮官？你怎麼會來這裡？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ผู้บัญชาการ? รู้ได้ไงว่าฉันอยู่ที่นี่?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tổng Tư Lệnh? Làm thế nào anh biết tôi ở đây?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "……指挥官？你怎么会来这里？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Offizier? Woher wusstest du, dass ich hier bin?"
L38_1.m_Talk_DEU = L39_1
