L39_1[L40_1] = true
L40_1 = "늦어서 죄송합니다. 주민들을 대피시키고 오는 길입니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "遅れて申し訳ありません。住民を避難させてきました。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I'm sorry for being late. I had to evacuate the village first."
L39_1.m_Talk_ENG = L40_1
L40_1 = "抱歉來晚了，我先疏散居民後才回來的。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ขอโทษที่มาช้านะครับ ผมต้องอพยพชาวบ้านก่อน"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi xin lỗi vì đã đến trễ. Tôi phải sơ tán dân làng trước."
L39_1.m_Talk_VTN = L40_1
L40_1 = "对不起，我来晚了。我先去疏散居民们了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Es tut mir leid, dass ich zu spät komme. Ich musste zuerst das Dorf evakuieren."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Désolé pour le retard, il fallait d'abord que j'évacue les villageois."
L39_1.m_Talk_FRA = L40_1
