L40_1[L41_1] = true
L41_1 = "엘라 대장이 장교님의 호위를 맡기로 했습니다만… 계획이 꼬여버린 모양이군요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "エラ隊長が将校の護衛を担当することになっていましたが……計画がこじれてしまったようですね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Captain Ella was supposed to be your bodyguard... But our plans appear to have gone awry."
L40_1.m_Talk_ENG = L41_1
L41_1 = "艾拉隊長決定擔任軍官的護衛…不過看來計劃有變。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "หัวหน้าเอลลาควรจะเป็นคนคุ้มกันคุณ... แต่ดูเหมือนเราจะผิดแผนซะแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đội trưởng Ella đáng lẽ sẽ là vệ sĩ của cô... Nhưng kế hoạch của chúng tôi dường như đã thất bại."
L40_1.m_Talk_VTN = L41_1
L41_1 = "艾拉队长说她负责保护军官……看来计划不是很顺利。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Kommandantin Ella sollte Ihre Leibwächterin sein ... Es sieht so aus, als wäre der Plan schiefgegangen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "La capitaine Ella devait s'occuper de votre sécurité, mais... on dirait que nos plans ont mal tourné."
L40_1.m_Talk_FRA = L41_1
