L41_1[L42_1] = true
L42_1 = "문제가 생겼어! 저건 이제 한나가 아니라 그림자다!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "問題が発生した！　あれはもうハンナではなく、シャドウだ！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "We have a problem! That's not Hanna anymore! She's a Shadow!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "大事不好！那個不是漢娜，而是暗影！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เรามีปัญหาแล้ว! นั่นไม่ใช่ฮันนาแล้ว! มันคือแชโดว์!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Chúng ta có một vấn đề! Đó không phải là Hanna nữa! Cô ấy là một Cái Bóng!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "出问题了！那个现在不是汉娜了，是暗影！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wir haben ein Problem! Das ist nicht mehr Hanna Anderson! Sie ist ein Schatten!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est terrible ! Hanna, elle n'est... ce n'est plus Hanna ! C'est une Ombre !"
L41_1.m_Talk_FRA = L42_1
