L42_1[L43_1] = true
L43_1 = "…알고 있습니다. 기억 속에서도 비슷한 연주소리를 들었으니까요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……わかっています。記憶の中でも似たような演奏を聞きましたから。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I know. I can remember that distinct sound from my memories."
L42_1.m_Talk_ENG = L43_1
L43_1 = "…我知道，因爲記憶中也有聽到類似的演奏聲。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ครับ ผมจำเสียงที่ไม่เหมือนใครนั่นได้จากในความทรงจำ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi biết. Tôi có thể nhớ âm thanh khác biệt đó từ ký ức của mình."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……我知道。因为记忆中我也听到过类似的演奏声。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich weiß. Ich habe in meiner Erinnerung eine ähnliche Aufführung gehört."
L42_1.m_Talk_DEU = L43_1
L43_1 = "... Je sais. Cette musique, c'est la même que dans mes souvenirs."
L42_1.m_Talk_FRA = L43_1
