L44_1 = "경황상 저희가 찾은 건, 성유물이 아니었던 모양이군요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "状況を察するに、我々が見つけたものは聖遺物ではなかったようですね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It turns out what we brought back wasn't the Holy Relic."
L43_1.m_Talk_ENG = L44_1
L44_1 = "根據情况，我們找到的好像不是聖遺物。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "กลายเป็นว่าที่เราเอากลับมาไม่ใช่สิ่งตกทอดศักดิ์สิทธิ์ไปซะได้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Hóa ra thứ chúng ta mang về không phải là Thánh Tích."
L43_1.m_Talk_VTN = L44_1
L44_1 = "从目前的情况来看，我们找到的似乎不是圣遗物。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Das, was wir mitgebracht haben, ist übrigens nicht das Heilige Artefakt."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Cet objet que nous avons rapporté, ce n'était pas la Sainte Relique."
