L45_1.m_fTalkTime = 0.03
L46_1 = "そばにいる人を疑わなかった私の失敗だ。まさか彼女があんなことをするとは……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "It's my fault for not suspecting the person beside me. But I never thought she would do such a thing..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "都怪我對身邊的人太大意，沒想到她會做出那種事……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ความผิดฉันเองแหละที่ไม่สงสัยคนใกล้ตัว แต่ฉันไม่เคยนึกเลยว่าเธอจะทำอะไรแบบนั้น..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Là lỗi của tôi khi không nghi ngờ người bên cạnh mình. Nhưng tôi không bao giờ nghĩ rằng cô ấy sẽ làm một điều như vậy..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "是我的失误，没有怀疑身边的人。我没想过她会做出那种事……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Es ist meine Schuld, dass ich die Person an meiner Seite nicht verdächtigt habe. Aber ich hätte nie gedacht, dass sie so etwas tun würde ..."
L45_1.m_Talk_DEU = L46_1
L46_1 = "C'est ma faute, je ne l'ai pas soupçonnée un seul instant alors qu'elle était avec moi tout ce temps. Je n'imaginais pas qu'elle puisse faire une chose pareille..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
