L47_1 = "m_CharScaleTime"
L48_1 = 0.01
L46_1[L47_1] = L48_1
L47_1 = "m_bCharPinup"
L46_1[L47_1] = true
L47_1 = "우린 지금 어디로 가는 거지?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私たちは今どこへ向かっているんだ？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Where are we headed right now?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我們現在要去哪裡?"
L46_1.m_Talk_TWN = L47_1
L47_1 = "นี่เรากำลังจะไปไหนกันนะ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chúng ta đang đi đâu bây giờ?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "我们现在要去哪儿？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Wohin gehen wir gerade?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Où est-ce que tu m'emmènes ?"
L46_1.m_Talk_FRA = L47_1
