L48_1 = "m_bCharPinup"
L47_1[L48_1] = true
L48_1 = "정신이 온전한 병사들을 동문 외곽 쪽으로 소집했습니다. 그쪽에서 재집결해 다시 돌아올 겁니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "精神に異常がない兵士を東門外郭の方に招集しておきました。そちらで再集結してまた戻ってくる予定です。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "All the unaffected soldiers are gathered outside the east gate. We'll head back once we regroup."
L47_1.m_Talk_ENG = L48_1
L48_1 = "把精神還沒崩潰的士兵聚集在東門外，在那裡重新整頓後再回來。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ทหารที่ไม่ได้รับผลกระทบทุกคนรวมตัวกันอยู่ที่นอกประตูตะวันตกครับ รวมกลุ่มกันใหม่แล้วเราจะกลับไป"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tất cả những người lính không bị ảnh hưởng đang tập trung bên ngoài cổng phía đông. Chúng ta sẽ quay trở lại sau khi chúng ta tái hợp."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我把精神正常的士兵们都召集到东门外了。我们会在那里重新集结。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Alle nicht betroffenen Soldaten sind vor dem Osttor versammelt. Sobald wir uns neu formiert haben, kehren wir zurück."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Tous les soldats non affectés sont rassemblés à la porte est. Allons les rejoindre pour préparer une contre-offensive."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
