L49_1 = "m_bCharPinup"
L48_1[L49_1] = true
L49_1 = "…수비대장이 이곳의 유일한 카운터야."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……守備隊長はここの唯一のカウンターだ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "The Guard Captain is the only Counter here."
L48_1.m_Talk_ENG = L49_1
L49_1 = "…護衛隊長可是這裡唯一的制裁者。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ที่นี่มีหัวหน้าองครักษ์เป็นเคาน์เตอร์อยู่คนเดียว"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đội trưởng Đội cảnh vệ là Counter duy nhất ở đây."
L48_1.m_Talk_VTN = L49_1
L49_1 = "……护卫队队长是这里唯一的制裁者。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Die Grenzschutzkommandantin ist der einzige Counter hier."
L48_1.m_Talk_DEU = L49_1
L49_1 = "... La capitaine est la seule Counter, ici."
L48_1.m_Talk_FRA = L49_1
