L51_1 = 0.01
L49_1[L50_1] = L51_1
L50_1 = "m_bCharPinup"
L49_1[L50_1] = true
L50_1 = "그녀가 그렇게 쉽게 당했다는 건, 평범한 인간들만으론 상대가 불가능하다는 거다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "彼女があんなに簡単にやられたということは、普通の人間では相手できないということだ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "If she went down so easily it'll be impossible for us to fight her."
L49_1.m_Talk_ENG = L50_1
L50_1 = "連她都一下就遇害，一般人是無法應付的。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ถ้าเธอยังแพ้ง่ายขนาดนั้น เราเองก็คงสู้ไม่ได้หรอก"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nếu cô ấy gục ngã dễ dàng như vậy thì chúng ta sẽ không thể chống lại cô ta."
L49_1.m_Talk_VTN = L50_1
L50_1 = "连她都那么容易就被打败了，说明光靠普通人根本对付不了那家伙。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Die Tatsache, dass sie so leicht besiegt wurde, bedeutet, dass es unmöglich für gewöhnliche Menschen wie uns ist, allein mit ihr fertig zu werden."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Si elle s'est fait vaincre aussi facilement... je ne vois pas ce qu'on peut faire."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
