L52_1 = {}
L53_1 = 1.4
L54_1 = 1.4
L52_1[1] = L53_1
L52_1[2] = L54_1
L50_1[L51_1] = L52_1
L51_1 = "m_CharScaleTime"
L52_1 = 0.01
L50_1[L51_1] = L52_1
L51_1 = "m_bCharPinup"
L50_1[L51_1] = true
L51_1 = "이성적으로 생각해라. 지금은 도망쳐야 해. 내가 왕실에 지원을 요청하겠다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "理性的に考えろ。今は逃げるべきなんだ。私が王室に支援を要請しよう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Think rationally. We need to escape now. I'll request backup from the capital."
L50_1.m_Talk_ENG = L51_1
L51_1 = "要冷靜地想想，現在必須逃跑，我要向皇室請求支援。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ถ้าคิดให้มีเหตุผล เราควรนี้กันตอนนี้นะ ฉันจะไปขอกำลังสนับสนุนจากเมืองหลวง"
L50_1.m_Talk_THA = L51_1
L51_1 = "Lý trí mà nói. Chúng ta cần phải trốn thoát ngay bây giờ. Tôi sẽ yêu cầu hỗ trợ từ thủ đô."
L50_1.m_Talk_VTN = L51_1
L51_1 = "理智一点！现在必须逃跑了！我会向王室请求支援。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Denken wir mal rational. Wir müssen jetzt fliehen. Ich werde Unterstützung aus der Hauptstadt anfordern."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Réfléchis, commandant. Nous devons nous replier. Rentrons à la capitale pour demander des renforts."
L50_1.m_Talk_FRA = L51_1
