L2_1 = "m_bCharPinup"
L1_1[L2_1] = true
L2_1 = "국경수비대가 외성을 포기하고 물러나면, 이곳을 믿고 있던 도시 전체가 위험해집니다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "国境守備隊が外郭を諦めて退却すれば、ここを信じていた都市全体が危険になります。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "If Border Guards give up on the outer castle, then all the cities that rely on us will be in danger."
L1_1.m_Talk_ENG = L2_1
L2_1 = "如果國境護衛隊放棄外城，我想這整個都市都會變得很危險。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ถ้าองครักษ์พิทักษ์ชายแดนยอมทิ้งปราสาทชั้นนอก ทุกเมืองที่หวังพึ่งเราก็จะตกอยู่ในอันตรายนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nếu Cảnh vệ Biên phòng từ bỏ lâu đài bên ngoài, thì tất cả các thành phố tin tưởng vào chúng tôi sẽ gặp nguy hiểm."
L1_1.m_Talk_VTN = L2_1
L2_1 = "要是边境护卫队放弃外城撤退的话，整个城市都会陷入危险的。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wenn die Grenzschutzbeamten die Außenburg aufgeben, sind alle Städte, die auf uns angewiesen sind, in Gefahr."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Si les garde-frontières abandonnent le fort, alors tous les villages qui comptent sur notre protection seront en danger."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
