L2_1[L3_1] = L4_1
L3_1 = "m_CharScaleTime"
L4_1 = 0.01
L2_1[L3_1] = L4_1
L3_1 = "m_bCharPinup"
L2_1[L3_1] = true
L3_1 = "지원을 기다리더라도, 저희는 이곳에서 버텨야만 합니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "支援を待つとしても、我々はここで耐えなければいけません。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Even if we wait until backup arrives, we need to hold our ground here."
L2_1.m_Talk_ENG = L3_1
L3_1 = "就算要等待支援，我們也必須堅持在這裡。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ต่อให้เรารอจนกว่ากำลังสนับสนุนมาถึง เราก็ต้องรักษาที่มั่นที่นี่ไว้อยู่ดี"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ngay cả khi chúng tôi đợi cho đến khi hỗ trợ đến, chúng tôi cần phải giữ vững hàng rào của mình ở đây."
L2_1.m_Talk_VTN = L3_1
L3_1 = "即使要等待支援，我们也必须死守这里。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Selbst wenn wir warten, bis Verstärkung eintrifft, müssen wir uns hier behaupten."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Même en demandant des renforts, nous devons tenir notre position ici."
L2_1.m_Talk_FRA = L3_1
