L8_1 = "침식체?! 어디서 나타난 거지?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "侵食体！？　どこから現れたんだ？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "A C.O.?! Where did it come from?!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "侵蝕體？！是從哪裡出現的？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "วัตถุคอร์รัปต์เหรอ? มันมาจากไหนกัน?!"
L7_1.m_Talk_THA = L8_1
L8_1 = "V.T.A.M?! Nó từ đâu đến?!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "侵蚀体？！是从哪里冒出来的？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ein C. O.?! Wo ist das denn hergekommen?!"
