L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "…아무래도 포위당한 것 같습니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "……どうやら取り囲まれたようですね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I think we've been surrounded."
L8_1.m_Talk_ENG = L9_1
L9_1 = "…我們似乎被包圍了。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ผมว่าเราโดนล้อมแล้วนะครับ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi nghĩ chúng ta đã bị bao vây."
L8_1.m_Talk_VTN = L9_1
L9_1 = "……我们好像被包围了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich glaube, wir wurden umzingelt."
L8_1.m_Talk_DEU = L9_1
L9_1 = "... Nous sommes encerclés."
L8_1.m_Talk_FRA = L9_1
