L10_1 = "BORDER_ACT2_INTERLUDE6@309#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 309
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4500212
L9_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "CURIAN_BORDER_NULL_FAKE"
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "침식체가 스스로 보일만한 행동체계는 아니군요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "侵食体が普段見せるような行動体系ではありません。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "This isn't something C.O.s would be able to do by themselves."
L9_1.m_Talk_ENG = L10_1
L10_1 = "原來侵蝕體無法憑著所見行動。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นี่ไม่ใช่เรื่องที่วัตถุคอร์รัปต์จะทำเองได้เลย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đây không phải là điều mà V.T.A.M có thể tự làm được."
L9_1.m_Talk_VTN = L10_1
L10_1 = "侵蚀体自己可做不出这样成体系的行动。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "C.°O.s sind normalerweise nicht in der Lage, so etwas von selbst zu tun."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Une manoeuvre pareille... impossible que ces monstres puisse la diriger par eux-mêmes."
L9_1.m_Talk_FRA = L10_1
