L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 312
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4500212
L12_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_DESPAIR"
L13_1 = "CYMBALS_NPC_NULL_HANNA"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "그렇게 쉽게 놓칠 줄 알았나요?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そんなに簡単に逃すと思ったんですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Did you really think I'd let you go so easily?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你以爲我會輕易放過你嗎?"
L12_1.m_Talk_TWN = L13_1
L13_1 = "คิดว่าฉันจะปล่อยพวกเธอไปง่ายๆ หรา?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Cô thực sự nghĩ rằng tôi sẽ để cô đi dễ dàng như vậy sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "你以为会那么容易逃走吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Haben Sie wirklich geglaubt, ich würde Sie so einfach gehen lassen?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Vous pensiez vraiment que j'allais vous laisser partir aussi facilement ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "BORDER_ACT2_INTERLUDE6@313#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 313
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4500212
L13_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_HATE"
L13_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "이 침식체들은 전부 네놈이 끌어들인 건가?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "この侵食体は全部貴様が引き入れたのか？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Are you the one controlling these C.O.s?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "這些侵蝕體都是你引來的嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แกเหรอที่ควบคุมวัตถุคอร์รัปต์พวกนี้น่ะ?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cô kiểm soát lũ V.T.A.M này sao?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "这些侵蚀体全都是你召唤过来的吗？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Bist du diejenige, die diese C.°O.s kontrolliert?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "C'est toi qui contrôle tous ces Objets Corrompus ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "BORDER_ACT2_INTERLUDE6@314#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 314
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4500212
L14_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_LAUGH"
L14_1.m_Face = L15_1
L15_1 = "CYMBALS_NPC_NULL_HANNA"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "맞아요. 침식체들도 제 연주를 정말 좋아하는 것 같더라고요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そうですよ。侵食体も私の演奏がとても好きみたいなんです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yes. It turns out that they love to hear me perform."
L14_1.m_Talk_ENG = L15_1
L15_1 = "沒錯，侵蝕體好像也很喜歡我的演奏。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ใช่ กลายเป็นว่าพวกมันชอบการแสดงของฉันเฉยเลย"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đúng. Hóa ra là chúng thích nghe tôi biểu diễn."
L14_1.m_Talk_VTN = L15_1
L15_1 = "没错。看来侵蚀体好像也很喜欢我的演奏呢。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "So ist es. Die C.°O.s scheinen mein Spiel wirklich zu mögen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "En effet. On dirait que ma musique leur plaît."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "BORDER_ACT2_INTERLUDE6@315#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 315
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4500212
L15_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "VIVIEN_OPR_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그림자의 힘으로… 침식체를 조종한다고?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "シャドウの力で……侵食体を操るだと？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "You can control C.O.s... with the power a Shadow?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "以暗影的力量…控制侵蝕體？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แกควบคุมวัตถุคอร์รัปต์ได้... ด้วยพลังของแชโดว์เหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cô có thể điều khiển V.T.A.M.. với sức mạnh của Cái Bóng?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "利用暗影的力量……操控侵蚀体？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Du kannst C.°O.s ... mit der Kraft eines Schattens steuern?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "La puissance d'une Ombre... te permet de contrôler des O.C. ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "BORDER_ACT2_INTERLUDE6@316#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 316
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4500212
L16_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "CYMBALS_NPC_NULL_HANNA"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "후후, 멋지지 않나요? 이 악기의 힘이라면 뭐든지 이룰 수 있을 거예요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ふふ、素敵じゃないですか？　この楽器の力があればなんでも叶えられるはずです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Fu fu. Isn't it wonderful? With this instrument's powers, there’s nothing I can’t do!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "呵呵，不覺得很帥嗎？只要有這個樂器的力量，就什麼都能實現。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หุหุ ยอดไปเลยไม่ใช่เหรอ? ถ้ามีพลังของเครื่องดนตรีชิ้นนี้ ก็ไม่มีอะไรที่ฉันทำไม่ได้หรอก!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Phu phu. Không phải thật tuyệt vời sao? Với sức mạnh của nhạc cụ này, không có gì tôi không thể làm được!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "呵呵，不觉得很酷吗？利用这个乐器的力量，就什么都能实现。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Haha. Ist es nicht cool? Mit den Kräften dieses Instruments gibt es nichts, was ich nicht tun kann!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Hu hu. N'est-ce pas merveilleux ? Avec les pouvoirs de cet instrument, rien ne peut m'arrêter !"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "BORDER_ACT2_INTERLUDE6@317#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 317
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4500212
L17_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SERIOUS"
L18_1 = "CYMBALS_NPC_NULL_HANNA"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "지금 감정은 어때요? 절망스럽나요?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今の感情はどうですか？　絶望的ですか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "What do you feel right now? Is it despair?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "你現在感覺怎麼樣？很絕望嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "รู้สึกยังไงล่ะทีนี้? สิ้นหวังปะนะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô cảm thấy gì ngay bây giờ? Có phải là tuyệt vọng không?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "现在感觉如何？绝望吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Was fühlen Sie gerade? Ist es Verzweiflung?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Que ressentez-vous en ce moment ? Le désespoir ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "BORDER_ACT2_INTERLUDE6@318#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 318
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4500212
L18_1.m_CutScenStrID = "BORDER_ACT2_INTERLUDE6"
L18_1.m_bWaitClick = true
