L19_1 = "CYMBALS_NPC_NULL_HANNA"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "이걸로 당신들이 살아남을 수 있는 길은…"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "これであなたたちが生き残れる方法は……"
