L19_1 = "Now, there's no escaping─"
L18_1.m_Talk_ENG = L19_1
L19_1 = "我要用這個將你們的生存之路…"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เอาล่ะ ไม่มีทางหนี–"
L18_1.m_Talk_THA = L19_1
