L18_1.m_Talk_VTN = L19_1
L19_1 = "这下你们就再也没有办法逃走……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Jetzt gibt es kein Entrinnen ─"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Tant mieux, car il n'y a pas d'échappat─"
L18_1.m_Talk_FRA = L19_1
