L23_1[L24_1] = L25_1
L24_1 = "…후후, 당신들은 참 고집스럽네요. 총알 따위는 소용없다는 걸 꼭 해봐야 아는 건가요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……ふふ、あなたたちって本当に頑固ですね。銃弾なんて無駄だってこと、やってみないとわからないんですか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Fu fu... Stubborn, are we? I thought I told you that bullets won't work on me."
L23_1.m_Talk_ENG = L24_1
L24_1 = "…呵呵，你們真固執，子彈這種東西是沒有用的，一定要試一下才罷休嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "หุหุ... ดันทุรังจังเนอะว่ามั้ย? ก็ว่าบอกไปแล้วน้อว่ากระสุนใช้กับฉันไม่ได้หรอก"
L23_1.m_Talk_THA = L24_1
L24_1 = "Phu phu... Bướng bỉnh thế nhỉ? Tôi đã nói với cô rằng đạn sẽ không có tác dụng với tôi mà."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……呵呵，你们真是固执啊。都说了子弹之类的对我没有用，你们非得要试试才知道吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... Haha, sind Sie doch so stur? Ich dachte, ich hätte Ihnen bereits gesagt, dass Kugeln mir nichts anhaben können."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Hu hu... têtu, n'est-ce pas ? Je vous ai déjà dit que les balles ne fonctionnent pas sur moi."
L23_1.m_Talk_FRA = L24_1
