L44_1 = "포위망을 뚫었을 뿐입니다. 곧 다시 쫓아오겠죠."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "包囲網を突破しただけです。すぐまた追ってくるでしょう。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It just made an opening for us to escape. They'll be chasing us again soon."
L43_1.m_Talk_ENG = L44_1
L44_1 = "只是突破包圍而已，很快就會再追上來的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แค่เปิดทางให้เราหนีน่ะ เดี๋ยวพวกมันก็ตามมาอีก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nó chỉ mở đường cho chúng ta trốn thoát thôi. Chúng sẽ đuổi theo chúng ta sớm thôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "只是突围了而已。马上又会追来的。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es hat uns gerade eine Möglichkeit zur Flucht eröffnet. Sie wird uns bald wieder verfolgen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Cette manoeuvre nous fera juste gagner un peu de temps. L'ennemi sera bientôt à nos trousses."
