L46_1[L47_1] = true
L47_1 = "엘라 대장이 당한 이상, 지금 저희 수비대의 힘만으론 그 자를 상대할 수 없습니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "エラ隊長がやられた以上、今の守備隊の力だけではあの者と立ち向かうことは不可能です。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "With Captain Ella down, we don't stand a chance against her."
L46_1.m_Talk_ENG = L47_1
L47_1 = "既然艾拉隊長已經遇害，現在單憑我們護衛隊的力量是無法對付他的。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "พอหัวหน้าเอลลาแพ้ไปแล้วเราก็ไม่มีโอกาสสู้ได้เลย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đội trưởng Ella đã gục ngã, chúng ta không có cơ hội chống lại cô ta."
L46_1.m_Talk_VTN = L47_1
L47_1 = "艾拉队长受伤了，现在只靠我们护卫队的力量，对付不了那家伙。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Da Kommandantin Ella ist bereits gefallen, also hat der Grenzschutz erst recht keine Chance gegen sie."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Sans la capitaine Ella, nous n'avons aucune chance contre cette chose."
L46_1.m_Talk_FRA = L47_1
